'use strict';
// Motor compartido por el diccionario y sus pruebas: relevancia antes que menciones incidentales.
window.RI_BUSCAR_GLOSARIO = (entries, query = '', options = {}) => {
  const norm = value => String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[¿?¡!]/g,'').toLowerCase().trim();
  const stopWords=new Set(['que','es','un','una','el','la','los','las','de','del','por','favor','significa','cual']);
  const q = norm(query), rawTokens=q.split(/\s+/).filter(Boolean), tokens=rawTokens.filter(token=>!stopWords.has(token));
  const terms=tokens.length?tokens:rawTokens;
  const clean=terms.join(' ');
  const exact=entries.filter(item=>[item.label,...item.aliases].some(name=>norm(name)===q||norm(name)===clean));
  const score = item => {
    const names = [item.label, ...item.aliases].map(norm);
    if (!q) return 1;
    if (names.includes(q)||names.includes(clean)) return 100;
    if (exact.length && !options.fullText) return 0;
    if (names.some(name => name.startsWith(q))) return 80;
    if (names.some(name => terms.every(token => name.split(/[^\p{L}\p{N}]+/u).some(word => word.startsWith(token))))) return 60;
    return options.fullText && terms.every(token => norm(item.definition+' '+item.use).includes(token)) ? 10 : 0;
  };
  return entries.filter(item => (!options.category || options.category === 'Todas' || item.category === options.category) && (!options.letter || item.label[0].localeCompare(options.letter,'es',{sensitivity:'base'}) === 0))
    .map(item => ({item, rank:score(item)})).filter(row => row.rank > 0)
    .sort((a,b) => b.rank-a.rank || a.item.label.localeCompare(b.item.label,'es')).map(row => row.item);
};
/* Diccionario didáctico. Las fuentes enlazadas son instrumentos y portales oficiales. */
window.RI_GLOSARIO = [
  {id:'hecho',label:'Hecho',aliases:['hechos','qué es un hecho','hecho del caso'],category:'Hechos y prueba',definition:'Acontecimiento, acción, omisión o circunstancia relevante para analizar un asunto. En un expediente se distingue lo que una parte afirma que ocurrió de lo que el órgano considera establecido mediante la prueba y las reglas aplicables.',use:'Ejemplo hipotético: «La persona ingresó al hospital el 3 de mayo» describe un hecho; «el Estado violó la Convención» formula una conclusión jurídica. Reglamento de la Corte, artículos 40.2.a y 41.1.a.',section:'#recorrido?paso=1',related:['hecho-alegado','hecho-probado','hecho-controvertido','marco-factico','prueba'],source:'https://www.oas.org/es/cidh/mandato/Basicos/reglamentoCorte.asp'},
  {id:'hecho-alegado',label:'Hecho alegado',aliases:['hechos alegados','alegación fáctica','afirmación de hecho'],category:'Hechos y prueba',definition:'Acontecimiento o circunstancia que una parte afirma que ocurrió. La afirmación debe distinguirse de la valoración que hará el órgano sobre si puede tenerse por establecida.',use:'En el supuesto hospitalario, que una parte afirme que se negó atención todavía exige identificar qué información sustenta esa versión y qué responde el Estado. Reglamento de la Corte, artículos 40–41.',section:'#recorrido?paso=8',related:['hecho','hecho-probado','hecho-controvertido','prueba'],source:'https://www.oas.org/es/cidh/mandato/Basicos/reglamentoCorte.asp'},
  {id:'hecho-probado',label:'Hecho probado',aliases:['hechos probados','hecho acreditado','hechos acreditados','hecho establecido'],category:'Hechos y prueba',definition:'Hecho que el órgano tiene por establecido tras examinar la información y aplicar las reglas pertinentes del procedimiento. No equivale a cualquier afirmación de una parte ni implica por sí solo que se haya declarado una violación.',use:'Puede acreditarse una fecha de ingreso y seguir discutiéndose si la atención brindada incumplió una obligación internacional. Reglamento de la Corte, artículos 57–58 y 65.1.d.',section:'#recorrido?paso=16',related:['hecho','hecho-alegado','prueba','fondo','responsabilidad-internacional'],source:'https://www.oas.org/es/cidh/mandato/Basicos/reglamentoCorte.asp'},
  {id:'hecho-controvertido',label:'Hecho controvertido',aliases:['hechos controvertidos','hecho discutido','controversia fáctica'],category:'Hechos y prueba',definition:'Hecho sobre cuya ocurrencia, características o alcance existen posiciones diferentes entre quienes intervienen. Identificarlo ayuda a precisar qué necesita aclararse mediante la prueba.',use:'Si una parte alega que se rechazó la atención y el Estado afirma que sí se prestó, hay una cuestión fáctica que debe analizarse. Reglamento de la Corte, artículo 41.1.a.',section:'#recorrido?paso=14',related:['hecho','hecho-alegado','hecho-probado','contestacion','prueba'],source:'https://www.oas.org/es/cidh/mandato/Basicos/reglamentoCorte.asp'},
  {id:'accion-estatal',label:'Acción estatal',aliases:['acción del Estado','actuación estatal','acto estatal'],category:'Responsabilidad internacional',definition:'Conducta activa cuya atribución al Estado y relación con una obligación internacional deben examinarse. Identificar que ocurrió una actuación no basta para concluir que fue ilícita internacionalmente.',use:'Identifica qué autoridad actuó, en qué función, cuándo y qué obligación se alega incumplida. Convención Americana, artículos 1.1 y 2.',section:'#recorrido?paso=1',related:['hecho','omision-estatal','atribucion-estatal','obligacion-internacional'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'omision-estatal',label:'Omisión estatal',aliases:['omisión del Estado','falta de actuación estatal','inacción estatal'],category:'Responsabilidad internacional',definition:'Falta de una actuación que se sostiene que el Estado debía realizar conforme a una obligación aplicable. Para analizarla hay que precisar el deber, las circunstancias y la posibilidad de actuación, sin deducir responsabilidad únicamente del resultado dañoso.',use:'Pregunta qué actuación era exigible y qué información permite sostener que no se realizó. Convención Americana, artículos 1.1 y 2.',section:'#recorrido?paso=8',related:['hecho','accion-estatal','atribucion-estatal','obligacion-internacional','responsabilidad-internacional'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'} ,
  {id:'cidh',label:'CIDH',aliases:['Comisión Interamericana de Derechos Humanos','Comisión Interamericana','Comisión'],category:'Siglas e instituciones',definition:'Órgano principal y autónomo de la OEA que promueve y protege los derechos humanos. Recibe peticiones individuales, examina sus requisitos y puede someter casos a la Corte cuando se cumplen las reglas aplicables.',use:'En la ruta, la petición comienza ante la Comisión; la CIDH no dicta la sentencia de la Corte.',section:'#comision',related:['sidh','peticion','admisibilidad','informe-fondo','corteidh'],source:'https://www.oas.org/es/cidh/'},
  {id:'corteidh',label:'Corte IDH',aliases:['Corte Interamericana de Derechos Humanos','Corte Interamericana','Corte'],category:'Siglas e instituciones',definition:'Tribunal regional que decide casos contenciosos respecto de Estados que reconocieron su competencia, además de ejercer su función consultiva. En un caso individual, normalmente lo recibe después del trámite ante la CIDH.',use:'En esta guía, la fase ante la Corte incluye escritos, excepciones, prueba, audiencia, sentencia y supervisión.',section:'#corte',related:['sidh','cidh','jurisdiccion','esap','sentencia'],source:'https://www.corteidh.or.cr/'},
  {id:'oea',label:'OEA',aliases:['Organización de los Estados Americanos'],category:'Siglas e instituciones',definition:'Organización regional de Estados de las Américas. La CIDH es uno de sus órganos y el sistema interamericano se desarrolla dentro de este marco institucional.',use:'La pertenencia a la OEA y la aceptación de la competencia contenciosa de la Corte son cuestiones distintas.',section:'#oea',related:['sidh','cidh','cadh'],source:'https://www.oas.org/es/'} ,
  {id:'cadh',label:'CADH',aliases:['Convención Americana sobre Derechos Humanos','Convención Americana','Pacto de San José'],category:'Siglas y normas',definition:'Tratado interamericano que reconoce derechos y establece obligaciones estatales. También regula aspectos centrales de la CIDH y la Corte, como peticiones, informes, sometimiento y competencia contenciosa.',use:'La guía cita, entre otros, sus artículos 44–51 y 61–69. La aplicación concreta depende del Estado y del caso.',section:'#biblioteca',related:['cidh','corteidh','agotamiento','jurisdiccion','informe-fondo'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'sidh',label:'SIDH',aliases:['Sistema Interamericano de Derechos Humanos','Sistema Interamericano'],category:'Siglas y conceptos',definition:'Conjunto regional de instituciones, tratados y procedimientos de protección de derechos humanos en las Américas. Sus órganos centrales en esta ruta son la CIDH y la Corte IDH.',use:'El recorrido explica una vía concreta del sistema: petición individual ante la Comisión y eventual caso ante la Corte.',section:'#sistema',related:['oea','cidh','corteidh','cadh'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/'},
  {id:'dadh',label:'DADH',aliases:['Declaración Americana de los Derechos y Deberes del Hombre','Declaración Americana'],category:'Siglas y normas',definition:'Instrumento regional de derechos humanos aprobado en 1948. La CIDH puede aplicarlo en el marco de sus competencias, incluso respecto de Estados miembros que no son parte de la Convención Americana.',use:'La ruta principal de esta página se concentra en la vía convencional; la Declaración es un fundamento distinto.',section:'#biblioteca',related:['cidh','cadh','sidh'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/'},
  {id:'esap',label:'ESAP',aliases:['Escrito de solicitudes, argumentos y pruebas','escrito de solicitudes argumentos y pruebas'],category:'Siglas y escritos',definition:'Escrito autónomo que presentan ante la Corte las presuntas víctimas o sus representantes. Reúne sus argumentos, pruebas y pretensiones, dentro del marco fáctico del caso sometido por la Comisión.',use:'El Reglamento de la Corte establece su contenido y el plazo para presentarlo desde la notificación correspondiente.',section:'#recorrido',related:['corteidh','marco-factico','contestacion','reparaciones'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'ong',label:'ONG',aliases:['organización no gubernamental','organización no gubernamental legalmente reconocida'],category:'Siglas y conceptos',definition:'Organización de la sociedad civil que no forma parte del gobierno. Una ONG legitimada puede presentar una petición ante la CIDH en nombre propio o de otras personas; eso no la convierte automáticamente en víctima.',use:'La legitimación para presentar la petición y la identificación de las presuntas víctimas son preguntas diferentes.',section:'#recorrido',related:['peticion','victima','cidh'],source:'https://www.oas.org/es/CIDH/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'peticion',label:'Petición individual',aliases:['petición','peticiones individuales'],category:'Etapas',definition:'Comunicación presentada ante la CIDH que alega una posible violación de derechos humanos atribuible a un Estado. La Comisión revisa competencia y requisitos de admisibilidad antes de estudiar el fondo.',use:'Presentar una petición no significa que ya se haya declarado una violación ni que el caso esté ante la Corte.',section:'#recorrido',related:['cidh','agotamiento','admisibilidad','peticionario'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fseapc%2Fpeticiones.asp'},
  {id:'comunicacion-interestatal',label:'Comunicación interestatal',aliases:['petición interestatal','comunicaciones interestatales','petición de un Estado contra otro'],category:'Etapas',definition:'Comunicación por la que un Estado parte denuncia ante la CIDH que otro Estado parte ha violado la Convención Americana. Su examen depende de las declaraciones de competencia previstas en el artículo 45.',use:'Se distingue de la petición individual del artículo 44 por quién la presenta y por las declaraciones necesarias para que la CIDH pueda conocerla.',section:'#comision',related:['peticion','cidh','cadh'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'denuncia-convencion',label:'Denuncia de la Convención',aliases:['denunciar la Convención Americana','retiro de la CADH','denuncia de tratado'],category:'OEA y tratados',definition:'Acto formal por el que un Estado parte comunica su decisión de retirarse de la Convención Americana. El artículo 78 exige que hayan transcurrido cinco años desde su entrada en vigor para ese Estado y establece que la denuncia produce efecto un año después de la notificación.',use:'No es una petición ante la CIDH ni equivale a denunciar la Carta de la OEA. Las obligaciones por hechos anteriores a la fecha efectiva no desaparecen; consulta también la OC-26/20.',section:'#oea',related:['cadh','peticion','competencia','jurisdiccion'],source:'https://www.oas.org/dil/esp/tratados_B-32_Convencion_Americana_sobre_Derechos_Humanos.htm'},
  {id:'peticionario',label:'Peticionario',aliases:['peticionaria','persona peticionaria','parte peticionaria'],category:'Personas y roles',definition:'Persona, grupo u organización que presenta la petición ante la CIDH. Puede no coincidir con la persona que alega haber sufrido la violación.',use:'Distingue quién presenta la petición de quiénes son las presuntas víctimas.',section:'#recorrido',related:['peticion','victima','representante'],source:'https://www.oas.org/es/CIDH/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'victima',label:'Presunta víctima',aliases:['presuntas víctimas','víctima','víctimas'],category:'Personas y roles',definition:'Persona a quien se atribuye haber sufrido la violación alegada. Se dice “presunta” mientras el caso está en trámite. Ante la Corte, su identificación se rige por las reglas del Reglamento y el marco del caso.',use:'No es necesariamente quien presentó la petición; revisa las reglas de identificación antes de plantear cambios.',section:'#recorrido',related:['peticionario','esap','marco-factico'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'representante',label:'Representante',aliases:['representantes','representación'],category:'Personas y roles',definition:'Persona que actúa procesalmente por las presuntas víctimas ante la Corte, conforme a las reglas del procedimiento. Puede presentar el ESAP y continuar la actuación autónoma de sus representadas.',use:'Su participación no elimina los límites del marco fáctico ni los requisitos procesales.',section:'#recorrido',related:['esap','victima','marco-factico'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'agotamiento',label:'Agotamiento de recursos internos',aliases:['agotamiento','recursos internos'],category:'Requisitos y etapas',definition:'Regla general según la cual deben utilizarse primero los recursos disponibles en el propio Estado que sean adecuados y efectivos para atender la violación alegada. La Convención contempla excepciones.',use:'No significa probar todos los trámites imaginables: se analiza qué recurso era idóneo y efectivo en las circunstancias.',section:'#recorrido',related:['cadh','peticion','plazo-razonable','admisibilidad'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'competencia',label:'Competencia',aliases:['competencia de la Comisión','competencia de la Corte'],category:'Requisitos y etapas',definition:'Facultad jurídica de un órgano para conocer un asunto. En la CIDH puede analizarse por persona, tiempo, lugar y materia; la competencia contenciosa de la Corte requiere además el consentimiento estatal correspondiente.',use:'Competencia y admisibilidad responden preguntas distintas.',section:'#sistema',related:['cidh','corteidh','jurisdiccion','admisibilidad'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'jurisdiccion',label:'Jurisdicción contenciosa',aliases:['jurisdicción de la Corte','competencia contenciosa'],category:'Requisitos y etapas',definition:'Facultad de la Corte para resolver controversias concretas entre partes. La ratificación de la Convención y el reconocimiento de la competencia contenciosa de la Corte son actos jurídicos distintos.',use:'Antes de asumir que la Corte puede decidir, verifica el reconocimiento aplicable al Estado y al período relevante.',section:'#corte',related:['corteidh','cadh','competencia'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'admisibilidad',label:'Admisibilidad',aliases:['admisible','requisitos de admisibilidad'],category:'Requisitos y etapas',definition:'Examen de si una petición puede ser estudiada por la CIDH a la luz de requisitos procesales, como agotamiento o excepción, plazo, ausencia de duplicidad y caracterización de los hechos.',use:'Que la petición sea admisible abre el análisis de fondo; no declara responsabilidad.',section:'#recorrido',related:['agotamiento','competencia','fondo','peticion','caracterizacion'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'fondo',label:'Fondo',aliases:['examen de fondo','fase de fondo'],category:'Requisitos y etapas',definition:'Etapa en la que se examinan los hechos, las pruebas y las obligaciones aplicables para determinar si hubo una violación. En la vía ante la CIDH puede culminar en un informe de fondo.',use:'Es una pregunta distinta de si la petición podía ser estudiada (admisibilidad).',section:'#recorrido',related:['admisibilidad','informe-fondo','cidh','sentencia'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'solucion-amistosa',label:'Solución amistosa',aliases:['acuerdo de solución amistosa','solución amistosa','asunto solucionado'],category:'Requisitos y etapas',definition:'Mecanismo disponible en cualquier etapa del examen de una petición o caso. La CIDH puede facilitarlo, pero requiere el consentimiento de ambas partes y debe fundarse en el respeto de los derechos humanos. Si hay acuerdo, la Comisión verifica el consentimiento de la víctima y aprueba el informe del artículo 49 de la Convención, que concluye el trámite ante la CIDH; luego puede supervisar el cumplimiento.',use:'Durante el período del artículo 51.1, que el asunto haya sido solucionado es una alternativa a someterlo a la Corte. Si el caso ya está ante la Corte, esta decide la procedencia y los efectos del acuerdo (Reglamento, arts. 63–64). No es lo mismo que un informe definitivo del artículo 47 del Reglamento de la CIDH.',section:'#recorrido',related:['cidh','peticion','cadh','periodo-articulo-51','informe-definitivo'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'informe-fondo',label:'Informe de fondo',aliases:['informe artículo 50','informe del artículo 50'],category:'Decisiones y documentos',definition:'Informe de la CIDH que expone hechos y conclusiones sobre el fondo. Si establece violaciones, el Reglamento contempla un informe preliminar con recomendaciones que se transmite al Estado. No es una sentencia de la Corte.',use:'Distingue el informe del artículo 50, su transmisión al Estado y el eventual informe definitivo regulado tras el período del artículo 51.',section:'#recorrido',related:['cidh','fondo','informe-preliminar','recomendaciones','periodo-articulo-51','informe-definitivo','sometimiento','sentencia'],source:'https://www.oas.org/dil/esp/tratados_B-32_convencion_americana_sobre_derechos_humanos.htm'},
  {id:'informe-preliminar',label:'Informe preliminar',aliases:['informe preliminar del artículo 50','informe confidencial de la CIDH','informe con recomendaciones al Estado'],category:'Decisiones y documentos',definition:'Tras establecer una o más violaciones en el examen de fondo, la CIDH prepara un informe preliminar con las proposiciones y recomendaciones que considere pertinentes y lo transmite al Estado. En esta etapa el Estado no está facultado para publicarlo hasta que la Comisión adopte una decisión. Se relaciona con el informe previsto en el artículo 50 de la Convención Americana.',use:'La fecha de transmisión a los Estados inicia el período del artículo 51.1. No es una sentencia ni el informe definitivo que la CIDH podría emitir después.',section:'#recorrido',related:['informe-fondo','recomendaciones','periodo-articulo-51','suspension-articulo-51','informe-definitivo','sometimiento'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'recomendaciones',label:'Recomendaciones de la CIDH',aliases:['recomendación','recomendaciones','cumplir las recomendaciones'],category:'Decisiones y documentos',definition:'Medidas que la Comisión propone al Estado en el informe de fondo cuando determina que hubo una o más violaciones. El Estado informa sobre las medidas adoptadas y la CIDH puede dar seguimiento. Las recomendaciones no son una sentencia de la Corte.',use:"No equivalen a una sentencia judicial, pero tampoco deben presentarse como jurídicamente irrelevantes. Estudia la buena fe y el deber de realizar los mejores esfuerzos para cumplirlas en Loayza Tamayo (sentencia de 17 de septiembre de 1997, párrs. 79–81).",section:'#seguimiento',related:['informe-fondo','informe-preliminar','periodo-articulo-51','informe-definitivo','supervision','cidh'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'periodo-articulo-51',label:'Período de tres meses del artículo 51.1',aliases:['tres meses del artículo 51','plazo del artículo 51','período artículo 51','plazo de tres meses tras el informe'],category:'Plazos y escritos',definition:'Período que comienza cuando se remite a los Estados el informe de la Comisión previsto en el artículo 50. Si dentro de esos tres meses el asunto no se soluciona ni se somete a la Corte por la Comisión o por un Estado interesado que haya aceptado su competencia, la Comisión puede emitir su opinión y conclusiones conforme al artículo 51.1.',use:'No comienza con la notificación al peticionario. Contrástalo con el mes que el artículo 44.3 del Reglamento concede al peticionario para presentar su posición.',section:'#reloj',related:['informe-preliminar','notificacion','suspension-articulo-51','informe-definitivo','sometimiento'],source:'https://www.oas.org/dil/esp/tratados_B-32_convencion_americana_sobre_derechos_humanos.htm'},
  {id:'suspension-articulo-51',label:'Suspensión del período del artículo 51',aliases:['suspensión del plazo del artículo 51','prórroga del artículo 51','extensión del plazo de tres meses'],category:'Plazos y escritos',definition:'La CIDH puede considerar suspender el período de tres meses a solicitud del Estado. El Estado debe demostrar voluntad y capacidad de implementar recomendaciones con acciones concretas e idóneas, y aceptar expresa e irrevocablemente la suspensión y renunciar a plantear una excepción preliminar por incumplimiento de ese plazo si el caso llega a la Corte. La CIDH fija el período considerando factores como la complejidad, las medidas adoptadas y la posición del peticionario.',use:'La norma habla de suspensión, no de una prórroga automática. Explora esta condición desde la estación de remisión del informe y el comparador de plazos.',section:'#recorrido',related:['periodo-articulo-51','informe-preliminar','recomendaciones','sometimiento'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'informe-definitivo',label:'Informe definitivo de la CIDH',aliases:['informe final de la CIDH','informe artículo 51'],category:'Decisiones y documentos',definition:'Si vencen los tres meses desde la transmisión del informe preliminar sin que el asunto se haya solucionado ni sometido a la Corte, el Reglamento permite que la CIDH emita, por mayoría absoluta, un informe definitivo con su opinión, conclusiones finales y recomendaciones. Lo transmite a las partes; luego evalúa la información de cumplimiento y decide sobre su publicación.',use:'Es un acto posterior y distinto del informe preliminar del artículo 50 y de una sentencia de la Corte.',section:'#seguimiento',related:['informe-preliminar','periodo-articulo-51','recomendaciones','supervision','sentencia'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'sometimiento',label:'Sometimiento del caso',aliases:['someter el caso','presentación del caso ante la Corte'],category:'Etapas y documentos',definition:'Actuación por la que un asunto llega a la Corte para su conocimiento contencioso. En la vía de petición individual, la Comisión es quien puede someterlo conforme a las reglas aplicables.',use:'Sometimiento, notificación y presentación del ESAP son momentos distintos.',section:'#recorrido',related:['cidh','corteidh','esap','notificacion'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'notificacion',label:'Notificación',aliases:['notificaciones','notificado','notificada'],category:'Etapas y documentos',definition:'Comunicación formal de una actuación procesal a quienes intervienen. La fecha y el acto notificado pueden determinar desde cuándo corre un plazo.',use:'En la fase ante la Corte, cada plazo debe vincularse con su propia notificación o traslado.',section:'#reloj',related:['plazo','esap','contestacion','sometimiento'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'computo-plazos-cidh',label:'Cómputo de plazos de la CIDH (Resolución 4/26)',aliases:['resolución 4/26','días corridos CIDH','plazos CIDH','cómputo calendario'],category:'Plazos y escritos',definition:'La Resolución 4/26 aclara el cómputo de los plazos en los procedimientos de la CIDH: los plazos expresados en días se cuentan en días corridos; el conteo inicia el día del envío oficial de la comunicación y vence a las 24:00, hora de Washington, D. C. Si el vencimiento cae en día inhábil, pasa al siguiente día hábil. Para ciertos expedientes con informe de fondo pendientes de remisión o publicación, rigen las fechas indicadas en las notas respectivas.',use:'Identifica la fecha del envío oficial y revisa la comunicación del expediente. El reloj didáctico del Atlas no calcula feriados ni certifica vencimientos; no sustituye las reglas específicas de la Convención, el Reglamento o una decisión de suspensión.',section:'#reloj',related:['plazo','notificacion','periodo-articulo-51','suspension-articulo-51'],source:'https://www.oas.org/es/cidh/decisiones/pdf/2026/res-4-26.pdf'},
  {id:'plazo-razonable',label:'Plazo razonable',aliases:['razonable duración','retardo injustificado'],category:'Plazos y escritos',definition:'Criterio jurídico que valora si el tiempo transcurrido resulta justificable en las circunstancias. No es un número único de días aplicable a todos los casos.',use:'Aparece, entre otros contextos, al analizar excepciones relacionadas con recursos internos y la duración de actuaciones.',section:'#reloj',related:['agotamiento','plazo','admisibilidad'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'traslado',label:'Traslado',aliases:['dar traslado','trasladar'],category:'Plazos y escritos',definition:'Acto por el que se comunica un escrito o asunto a otra parte para que pueda conocerlo y responder. La fecha del traslado puede activar un plazo procesal.',use:'Identifica qué se trasladó, a quién y en qué fecha antes de calcular el plazo.',section:'#reloj',related:['notificacion','plazo','contestacion'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'contestacion',label:'Contestación del Estado',aliases:['contestación','escrito de contestación'],category:'Etapas y documentos',definition:'Escrito en que el Estado demandado fija su posición frente al caso y, cuando corresponda, frente al ESAP. Puede responder a hechos y pretensiones, ofrecer pruebas y plantear excepciones preliminares.',use:'Tiene un plazo propio que se cuenta desde la recepción de los escritos indicados en el Reglamento.',section:'#recorrido',related:['esap','excepcion','plazo','marco-factico'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'excepcion',label:'Excepción preliminar',aliases:['excepciones preliminares','excepción'],category:'Etapas y argumentos',definition:'Objeción procesal planteada por el Estado para cuestionar si la Corte puede conocer el caso o si se cumplieron ciertos requisitos procesales. Su naturaleza y momento deben analizarse según la regla invocada.',use:'No toda discrepancia con los argumentos de la CIDH constituye una excepción preliminar.',section:'#recorrido',related:['competencia','agotamiento','contestacion','corteidh'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'marco-factico',label:'Marco fáctico',aliases:['marco de hechos','marco del caso'],category:'Etapas y argumentos',definition:'Conjunto de hechos que delimita la controversia llevada ante la Corte, a partir de la presentación del caso por la Comisión y las reglas procesales. Orienta qué hechos pueden discutirse en los escritos posteriores.',use:'El ESAP permite argumentos y pretensiones autónomos dentro de ese marco; no autoriza a cambiarlo sin límites.',section:'#recorrido',related:['sometimiento','esap','victima','contestacion'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'mc',label:'Medidas cautelares',aliases:['medida cautelar','MC'],category:'Protección urgente',definition:'Mecanismo de la CIDH que puede solicitarse para atender situaciones de gravedad y urgencia con riesgo de daño irreparable, bajo los requisitos y procedimientos aplicables.',use:'No son la petición principal ni equivalen a las medidas provisionales de la Corte.',section:'#comision',related:['mp','cidh','corteidh'],source:'https://www.oas.org/es/cidh/decisiones/mc/'},
  {id:'mp',label:'Medidas provisionales',aliases:['medida provisional','MP'],category:'Protección urgente',definition:'Medidas urgentes que puede ordenar la Corte en casos de extrema gravedad y urgencia, y cuando sea necesario evitar daños irreparables, conforme a la Convención.',use:'Se distinguen de las medidas cautelares que tramita la CIDH.',section:'#corte',related:['mc','cidh','corteidh','cadh'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'prueba',label:'Prueba',aliases:['pruebas','medios de prueba'],category:'Prueba y decisión',definition:'Elemento ofrecido o presentado para sustentar hechos o argumentos, sujeto a las reglas de pertinencia, oportunidad y valoración del procedimiento.',use:'Distingue el tipo de prueba, el hecho que busca acreditar y la etapa en que se ofrece.',section:'#recorrido',related:['esap','perito','testigo','audiencia'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'perito',label:'Perito',aliases:['peritaje','peritos','experticia'],category:'Prueba y decisión',definition:'Persona con conocimientos especializados que puede aportar una opinión técnica sobre cuestiones relevantes del caso. Su ofrecimiento y declaración siguen reglas propias.',use:'Un peritaje no es lo mismo que un testimonio sobre hechos vividos.',section:'#recorrido',related:['prueba','testigo','audiencia','amicus'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'testigo',label:'Testigo',aliases:['testigos','declaración testimonial'],category:'Prueba y decisión',definition:'Persona que declara sobre hechos que conoce y que pueden ser relevantes para resolver el caso. La Corte regula su ofrecimiento, convocatoria y declaración.',use:'Diferéncialo de quien aporta una opinión experta como perito.',section:'#recorrido',related:['prueba','perito','audiencia'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'amicus',label:'Amicus curiae',aliases:['amicus','amigo del tribunal'],category:'Prueba y decisión',definition:'Presentación de una persona o institución ajena al litigio que ofrece información o argumentos sobre un asunto de interés. No convierte a quien la presenta en parte ni en perito.',use:'La Corte regula la recepción de escritos de amicus curiae.',section:'#recorrido',related:['prueba','corteidh','audiencia'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'audiencia',label:'Audiencia',aliases:['audiencia pública','debate oral'],category:'Prueba y decisión',definition:'Sesión oral del procedimiento en la que pueden recibirse declaraciones y escucharse argumentos, de acuerdo con lo que disponga la Corte. Su formato y duración dependen de cada caso.',use:'No todos los casos tienen idéntica audiencia ni un tiempo oral universal.',section:'#recorrido',related:['testigo','perito','alegatos','sentencia'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'alegatos',label:'Alegatos finales',aliases:['alegato final','alegatos'],category:'Prueba y decisión',definition:'Argumentos finales de las partes que explican cómo los hechos y las pruebas respaldan la posición jurídica que solicitan considerar. Pueden presentarse oralmente o por escrito según las decisiones del procedimiento.',use:'No confundas el tiempo para exponer en audiencia con el plazo para presentar alegatos escritos.',section:'#recorrido',related:['audiencia','prueba','sentencia'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'sentencia',label:'Sentencia',aliases:['sentencias','fallo'],category:'Prueba y decisión',definition:'Decisión judicial de la Corte que resuelve las cuestiones sometidas a su conocimiento y puede declarar responsabilidad y ordenar reparaciones. La Convención dispone que sus sentencias son definitivas e inapelables, y contempla la interpretación.',use:'La sentencia y el informe de fondo de la CIDH son documentos distintos.',section:'#recorrido',related:['corteidh','informe-fondo','reparaciones','supervision'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'reparaciones',label:'Reparaciones',aliases:['reparación integral','medidas de reparación'],category:'Prueba y decisión',definition:'Medidas que puede ordenar la Corte frente a las consecuencias de una violación declarada, conforme a las circunstancias del caso. Pueden incluir distintas formas de restitución, compensación, satisfacción o garantías de no repetición.',use:"Se solicitan desde el ESAP (art. 40.2.d) y el Estado las controvierte al contestar (art. 41.1.d). La Corte las decide a partir de la violación y sus consecuencias; pedirlas y resolverlas son actuaciones distintas.",section:'#recorrido',related:['sentencia','supervision','corteidh'],source:'https://www.corteidh.or.cr/reglamento.cfm'},
  {id:'supervision',label:'Supervisión de cumplimiento',aliases:['supervisión','cumplimiento de sentencia'],category:'Prueba y decisión',definition:'Seguimiento que realiza la Corte para verificar el cumplimiento de las reparaciones y demás medidas ordenadas en una sentencia.',use:'Una sentencia no termina necesariamente el trabajo: puede haber resoluciones de supervisión posteriores.',section:'#recorrido',related:['sentencia','reparaciones','corteidh'],source:'https://www.corteidh.or.cr/'},
  {id:'duplicidad',label:'Duplicidad internacional',aliases:['duplicidad','otro procedimiento internacional'],category:'Requisitos y etapas',definition:'Regla que examina si el asunto está siendo considerado o ya fue resuelto por otro procedimiento internacional, de acuerdo con los requisitos aplicables.',use:'Se analiza dentro de la admisibilidad y no es lo mismo que presentar recursos ante tribunales nacionales.',section:'#recorrido',related:['admisibilidad','peticion','cadh'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'caracterizacion',label:'Caracterización de una posible violación',aliases:['caracterización','caracterización inicial','caracterización de los hechos','caracterizar una posible violación'],category:'Requisitos y etapas',definition:'Examen inicial para establecer si los hechos alegados, de ser ciertos, podrían describir una violación de un derecho protegido por un instrumento interamericano aplicable.',use:'No determina responsabilidad ni sustituye el análisis de fondo. La Convención Americana aborda este requisito en el artículo 47(b).',section:'#recorrido',related:['admisibilidad','fondo','cadh'],source:'https://www.oas.org/dil/esp/tratados_B-32_convencion_americana_sobre_derechos_humanos.htm'},
  {id:'arcadia',label:'Arcadia',aliases:['caso Arcadia','Emilio Acosta'],category:'Caso de práctica',definition:'Expediente académico ficticio que se usa en la guía para practicar el análisis de etapas, escritos, plazos y argumentos. No describe un caso real de la Corte.',use:'Puedes seguir sus hitos en el caso de práctica y contrastarlos con las reglas generales.',section:'#arcadia',related:['peticion','esap','excepcion','sentencia'],source:null},
  {id:'ratione-personae',label:'Ratione personae',aliases:['competencia personal','competencia por razón de las personas','quién puede acudir'],category:'Competencia y jurisdicción',definition:'Pregunta quién puede activar el mecanismo, quién puede ser señalado como responsable y quiénes serían las presuntas víctimas. En la CIDH, el artículo 44 CADH permite presentar peticiones a personas, grupos y ONG legitimadas. Ante la Corte, la presentación de un caso contencioso sigue el artículo 61: pueden someterlo la Comisión o un Estado parte, no directamente una persona.',use:'Identifica por separado peticionario, presunta víctima y Estado; las reglas de legitimación ante la CIDH no crean acceso individual directo a la Corte.',section:'#competencia',related:['competencia','peticion','peticionario','victima','sometimiento','corteidh'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'ratione-temporis',label:'Ratione temporis',aliases:['competencia temporal','competencia por razón del tiempo','jurisdicción temporal'],category:'Competencia y jurisdicción',definition:'Pregunta si el instrumento y la aceptación de competencia estaban vigentes para el Estado cuando ocurrieron los hechos relevantes. Deben precisarse las fechas y distinguir actos, efectos y posibles violaciones continuadas según el caso y la jurisprudencia.',use:'No basta con que el Estado haya aceptado la competencia hoy: compara las fechas de los hechos con la entrada en vigor aplicable.',section:'#competencia',related:['competencia','jurisdiccion','cadh','ratione-loci'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'ratione-loci',label:'Ratione loci',aliases:['competencia territorial','competencia por razón del lugar','jurisdicción territorial'],category:'Competencia y jurisdicción',definition:'Pregunta si los hechos ocurrieron dentro del territorio del Estado o en circunstancias en las que las personas estaban bajo su jurisdicción conforme al instrumento aplicable. La ubicación geográfica es relevante, pero no siempre agota el análisis jurídico.',use:'Describe dónde ocurrieron los actos y qué relación de autoridad o control se alega; no concluyas solo por nacionalidad o fronteras.',section:'#competencia',related:['competencia','jurisdiccion-extraterritorial','ratione-personae','ratione-temporis'],source:'https://www.corteidh.or.cr/docs/opiniones/seriea_23_esp.pdf'},
  {id:'ratione-materiae',label:'Ratione materiae',aliases:['competencia material','competencia por razón de la materia','materia de competencia'],category:'Competencia y jurisdicción',definition:'Pregunta qué tratado, derechos y obligaciones puede examinar el órgano y qué alcance material le atribuye la norma de competencia. La mención interpretativa de un tratado no equivale por sí sola a competencia para declarar su violación autónoma.',use:'Nombra el derecho y el instrumento invocados; después identifica la disposición que habilita al órgano para conocerlos.',section:'#competencia',related:['competencia','uso-interpretativo-tratado','aplicacion-directa-tratado','cadh','protocolo-san-salvador','belem-do-para'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'consentimiento-estatal',label:'Consentimiento estatal',aliases:['consentimiento del Estado','aceptación estatal','consentimiento a la jurisdicción'],category:'Competencia y jurisdicción',definition:'Base jurídica por la que un Estado acepta una obligación o una competencia internacional mediante el instrumento y la forma previstos por el derecho aplicable. No se presume igual para todos los órganos ni para todos los tratados.',use:'Distingue ser miembro de la OEA, ratificar la Convención Americana y reconocer la competencia contenciosa de la Corte.',section:'#competencia',related:['reconocimiento-corte','clausula-facultativa','competencia','jurisdiccion','oea','cadh'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'reconocimiento-corte',label:'Reconocimiento de la competencia de la Corte',aliases:['declaración del artículo 62','aceptación de la jurisdicción de la Corte','reconocimiento de jurisdicción'],category:'Competencia y jurisdicción',definition:'Acto mediante el cual un Estado parte reconoce como obligatoria la competencia contenciosa de la Corte, por declaración incondicional, bajo condición de reciprocidad, por plazo determinado o para casos específicos, conforme al artículo 62 CADH.',use:'Comprueba la declaración oficial, sus condiciones y el período relevante para el Estado antes de afirmar que la Corte puede conocer.',section:'#competencia',related:['consentimiento-estatal','clausula-facultativa','jurisdiccion','cadh'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'clausula-facultativa',label:'Cláusula facultativa',aliases:['cláusula opcional','cláusula facultativa de aceptación'],category:'Competencia y jurisdicción',definition:'Disposición que permite a un Estado aceptar una competencia internacional mediante una declaración prevista en el instrumento. En el sistema interamericano, el artículo 62 CADH regula el reconocimiento de la jurisdicción contenciosa de la Corte.',use:'La ratificación de la Convención y la declaración del artículo 62 son actos distintos.',section:'#competencia',related:['reconocimiento-corte','consentimiento-estatal','clausula-compromisoria'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'clausula-compromisoria',label:'Cláusula compromisoria',aliases:['cláusula de solución de controversias','cláusula jurisdiccional en un tratado'],category:'Competencia y jurisdicción',definition:'Cláusula de un tratado que prevé un mecanismo para resolver controversias sobre su interpretación o aplicación. Su alcance se limita a las partes, materias y condiciones del instrumento; no es una aceptación general de cualquier jurisdicción internacional.',use:'Lee la cláusula concreta y verifica qué controversias cubre; no la equipares automáticamente a una declaración general de competencia.',section:'#competencia',related:['consentimiento-estatal','compromiso-especial','ratione-materiae'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'compromiso-especial',label:'Compromiso especial',aliases:['acuerdo especial de sometimiento','compromiso ad hoc'],category:'Competencia y jurisdicción',definition:'Acuerdo por el que los sujetos habilitados someten una controversia concreta a un órgano internacional cuando el régimen aplicable permite esa vía. No sustituye los requisitos de una petición individual ni amplía por sí solo la competencia material del órgano.',use:'Pregunta qué partes lo suscriben, qué controversia cubre y qué instrumento permite utilizarlo.',section:'#competencia',related:['clausula-compromisoria','consentimiento-estatal','peticion','sometimiento'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'atribucion-competencia',label:'Atribución de competencia',aliases:['atribución expresa','atribución tácita','atribución implícita','facultades atribuidas'],category:'Competencia y jurisdicción',definition:'Identificación de la norma que confiere una función a un órgano. Una atribución expresa aparece en el instrumento; una inferencia tácita requiere actos jurídicamente concluyentes y una base interpretativa; las facultades implícitas son instrumentales a funciones expresamente conferidas. Ninguna categoría crea competencia ilimitada.',use:'No mezcles atribución de competencia al órgano con atribución al Estado de una conducta ilícita.',section:'#competencia',related:['competencia','atribucion-estatal','consentimiento-estatal','facultades-implicitas'],source:'https://www.oas.org/juridico/spanish/carta.html'},
  {id:'facultades-implicitas',label:'Facultades implícitas',aliases:['competencias implícitas','poderes implícitos'],category:'Competencia y jurisdicción',definition:'Facultades instrumentales que un órgano internacional puede necesitar para cumplir funciones que le fueron expresamente atribuidas. Su reconocimiento depende del instrumento constitutivo y de la interpretación jurídica; no equivale al consentimiento estatal para una jurisdicción contenciosa ilimitada.',use:'La doctrina desarrollada para una organización no se traslada automáticamente a otra. Examina el instrumento constitutivo de la OEA y la función concreta.',section:'#competencia',related:['atribucion-competencia','competencia','consentimiento-estatal'],source:'https://www.icj-cij.org/case/4'},
  {id:'jurisdiccion-extraterritorial',label:'Jurisdicción extraterritorial',aliases:['jurisdicción fuera del territorio','aplicación extraterritorial'],category:'Competencia y jurisdicción',definition:'Posible ejercicio de jurisdicción estatal respecto de personas o hechos fuera del territorio, según las circunstancias y el criterio jurídico aplicable. La Corte IDH ha tratado obligaciones ambientales transfronterizas en su Opinión Consultiva OC-23/17; no es una regla automática para cualquier supuesto.',use:'Explica qué autoridad estatal actuó, sobre quién y dónde; contrasta la situación con la fuente y la jurisprudencia pertinente.',section:'#competencia',related:['ratione-loci','ratione-personae','competencia'],source:'https://www.corteidh.or.cr/docs/opiniones/seriea_23_esp.pdf'},
  {id:'funcion-contenciosa',label:'Función contenciosa',aliases:['jurisdicción contenciosa','caso contencioso'],category:'Competencia y jurisdicción',definition:'Función de la Corte IDH de resolver controversias concretas sobre el cumplimiento de la Convención y de otros instrumentos que le atribuyen competencia, respecto de Estados sujetos a su jurisdicción y dentro de los límites aplicables.',use:'Se activa mediante el sometimiento autorizado del caso; una persona no presenta directamente una demanda contenciosa ante la Corte.',section:'#corte',related:['funcion-consultiva','corteidh','sometimiento','reconocimiento-corte'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'funcion-consultiva',label:'Función consultiva',aliases:['competencia consultiva','opinión consultiva'],category:'Competencia y jurisdicción',definition:'Función de la Corte IDH para interpretar la Convención Americana y otros tratados de derechos humanos en los Estados americanos, a solicitud de los sujetos autorizados por el artículo 64 CADH. No resuelve una petición individual ni dicta una sentencia contenciosa.',use:'Usa el catálogo de opiniones consultivas para estudiar preguntas jurídicas generales y distingue las solicitudes aún pendientes de las opiniones emitidas.',section:'#opiniones',related:['corteidh','funcion-contenciosa','competencia'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'uso-interpretativo-tratado',label:'Uso interpretativo de otro tratado',aliases:['interpretación a la luz de otro tratado','referencia interpretativa','tratado como contexto interpretativo'],category:'Competencia y jurisdicción',definition:'Uso de un instrumento internacional para aclarar el sentido o alcance de una norma cuya aplicación sí está dentro de la competencia del órgano. La referencia interpretativa no concede automáticamente competencia para declarar la violación autónoma del tratado utilizado como contexto.',use:'Identifica qué norma sirve de fundamento directo y cuál se cita como apoyo interpretativo.',section:'#competencia',related:['ratione-materiae','aplicacion-directa-tratado','responsabilidad-internacional'],source:'https://www.corteidh.or.cr/docs/opiniones/seriea_17_esp.pdf'},
  {id:'aplicacion-directa-tratado',label:'Aplicación directa de un tratado',aliases:['aplicación directa','violación autónoma de un tratado'],category:'Competencia y jurisdicción',definition:'Aplicación de una disposición convencional como norma que rige directamente el análisis del órgano. Requiere que el tratado, el Estado y la materia estén dentro de la competencia atribuida; no basta que el tratado sea relevante para interpretar otra obligación.',use:'En el explorador de tratados, separa “materia interpretativa” de “disposición que permite una petición o decisión directa”.',section:'#competencia',related:['uso-interpretativo-tratado','ratione-materiae','competencia'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'obligacion-internacional',label:'Obligación internacional',aliases:['obligaciones internacionales','deber convencional'],category:'Responsabilidad internacional',definition:'Deber jurídico que vincula a un Estado conforme al tratado u otra norma internacional aplicable. Para evaluar una alegación, identifica el contenido de la obligación, su vigencia, la conducta estatal relacionada y la evidencia.',use:'Una decisión nacional desfavorable no demuestra por sí sola el incumplimiento de una obligación internacional.',section:'#recorrido',related:['responsabilidad-internacional','atribucion-estatal','cadh','fondo'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'atribucion-estatal',label:'Atribución de conducta al Estado',aliases:['atribución al Estado','conducta estatal','acto u omisión estatal'],category:'Responsabilidad internacional',definition:'Análisis para determinar si una acción u omisión puede considerarse jurídicamente conducta del Estado según las reglas aplicables. Debe examinarse quién actuó, con qué función o vínculo estatal y qué deber de actuación existía.',use:'Separa la conducta atribuible al Estado de la atribución de competencia a un órgano internacional.',section:'#recorrido',related:['atribucion-competencia','obligacion-internacional','responsabilidad-internacional','fondo'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'responsabilidad-internacional',label:'Responsabilidad internacional del Estado',aliases:['responsabilidad estatal','declaración de responsabilidad'],category:'Responsabilidad internacional',definition:'Consecuencia jurídica que puede declararse cuando se determina que una conducta atribuible al Estado incumplió una obligación internacional aplicable. En el sistema, la CIDH formula conclusiones y recomendaciones en sus informes; la Corte puede declarar responsabilidad en una sentencia dentro de su competencia.',use:'Distingue interpretación de una norma, aplicación directa y declaración de responsabilidad; identifica qué órgano emite cada decisión.',section:'#competencia',related:['obligacion-internacional','atribucion-estatal','informe-fondo','sentencia'],source:'https://www.corteidh.or.cr/docs/casos/articulos/seriec_4_esp.pdf'},
  {id:'protocolo-san-salvador',label:'Protocolo de San Salvador',aliases:['Protocolo adicional a la CADH en materia de DESC','PSS'],category:'Tratados interamericanos',definition:'Protocolo adicional a la Convención Americana sobre derechos económicos, sociales y culturales. Su artículo 19.6 prevé el sistema de peticiones individuales en los supuestos expresamente indicados de los artículos 8.a y 13.',use:"La limitación del artículo 19.6 no equivale a excluir toda justiciabilidad de otros derechos sociales: distingue la vía del Protocolo de la protección desarrollada por la Corte bajo el artículo 26 CADH, entre otros en Lagos del Campo (2017).",section:'#competencia',related:['ratione-materiae','aplicacion-directa-tratado','cadh','competencia'],source:'https://www.oas.org/es/cidh/mandato/Basicos/sansalvador.asp'},
  {id:'belem-do-para',label:'Convención de Belém do Pará',aliases:['Convención Interamericana para Prevenir, Sancionar y Erradicar la Violencia contra la Mujer','Belém do Pará'],category:'Tratados interamericanos',definition:"Tratado interamericano sobre violencia contra la mujer. Su artículo 12 prevé peticiones ante la CIDH sobre el artículo 7. En Campo Algodonero, la Corte reconoció competencia material respecto del artículo 7, y no de los artículos 8 y 9 (sentencia de 16 de noviembre de 2009, párr. 80). La competencia se analiza con los demás requisitos del caso.",use:'Comprueba el artículo y el órgano: la petición prevista en el artículo 12 se dirige a la CIDH.',section:'#competencia',related:['ratione-materiae','cidh','funcion-contenciosa','competencia'],source:"https://corteidh.or.cr/docs/casos/articulos/seriec_205_esp.pdf"},
  {id:'convencion-desaparicion-forzada',label:'Convención Interamericana sobre Desaparición Forzada de Personas',aliases:['Convención sobre Desaparición Forzada','CIDFP'],category:'Tratados interamericanos',definition:'Tratado regional que define y establece obligaciones respecto de la desaparición forzada. Su artículo XIII remite las peticiones a los procedimientos y órganos interamericanos conforme a la Convención Americana y a los estatutos y reglamentos aplicables.',use:'La remisión procedimental no elimina los requisitos de competencia propios de cada órgano.',section:'#competencia',related:['cidh','corteidh','ratione-materiae','competencia'],source:'https://www.oas.org/es/cidh/mandato/Basicos/desaparicion.asp'},
  {id:'convencion-derechos-nino',label:'Convención sobre los Derechos del Niño',aliases:['CDN','Convención de los Derechos del Niño'],category:'Tratados internacionales',definition:'Tratado de las Naciones Unidas que reconoce derechos de niñas, niños y adolescentes. Puede ser relevante para interpretar obligaciones interamericanas; cualquier mecanismo individual separado depende del protocolo correspondiente y de que el Estado sea parte.',use:'No confundas la relevancia interpretativa de la CDN con una atribución automática de competencia contenciosa a la Corte IDH.',section:'#competencia',related:['uso-interpretativo-tratado','aplicacion-directa-tratado','ratione-materiae'],source:'https://www.ohchr.org/en/instruments-mechanisms/instruments/convention-rights-child'},
  {id:'protocolo-comunicaciones-nino',label:'Protocolo facultativo de comunicaciones de la Convención sobre los Derechos del Niño',aliases:['Protocolo facultativo de comunicaciones','OPIC','Protocolo de comunicaciones de la CDN'],category:'Tratados internacionales',definition:'Protocolo de la ONU que establece un procedimiento de comunicaciones ante el Comité de los Derechos del Niño sujeto a sus requisitos y a la aceptación del Estado. Es un mecanismo distinto del procedimiento ante la CIDH y la Corte IDH.',use:'Antes de señalar una vía individual ante el Comité, verifica en el registro de tratados la condición del Estado y las declaraciones pertinentes.',section:'#competencia',related:['convencion-derechos-nino','uso-interpretativo-tratado','competencia'],source:'https://www.ohchr.org/en/instruments-mechanisms/instruments/optional-protocol-convention-rights-child-communications-procedure'},
  {id:'excepciones-agotamiento',label:'Excepciones al agotamiento de recursos internos',aliases:['excepción al agotamiento','falta de debido proceso','impedimento de acceso','retardo injustificado'],category:'Requisitos y etapas',definition:'La Convención contempla excepciones a la regla de agotamiento cuando no existe en el derecho interno debido proceso para proteger el derecho, se impide el acceso a los recursos o hay retardo injustificado en decidir. Su aplicación depende de los hechos y de las alegaciones de las partes.',use:'No basta nombrar una excepción: explica qué recurso era idóneo, qué ocurrió y qué evidencia respalda la circunstancia invocada.',section:'#recorrido',related:['agotamiento','plazo-razonable','admisibilidad','cadh'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'plazo-peticion-seis-meses',label:'Plazo de seis meses para presentar una petición',aliases:['seis meses','plazo de seis meses','artículo 46.1.b'],category:'Plazos y escritos',definition:'Regla general de oportunidad de una petición bajo la Convención Americana: debe presentarse dentro de los seis meses desde que la presunta víctima fue notificada de la decisión interna definitiva. La Convención prevé una regla distinta cuando aplica una excepción al agotamiento.',use:'El reloj es orientativo: verifica qué decisión es definitiva, cuándo se notificó y si se alega una excepción que cambie la regla aplicable.',section:'#reloj',related:['agotamiento','excepciones-agotamiento','peticion','admisibilidad','computo-plazos-cidh'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'informe-admisibilidad',label:'Informe de admisibilidad',aliases:['decisión de admisibilidad','informe de admisibilidad de la CIDH'],category:'Decisiones y documentos',definition:'Decisión de la CIDH sobre si una petición cumple los requisitos procesales para pasar al examen de fondo. La admisibilidad no determina que hubo una violación; si se declara admisible, el asunto se registra como caso y comienza el procedimiento de fondo conforme al Reglamento.',use:"Distingue admisibilidad, inadmisibilidad y archivo (arts. 36 y 42 Reglamento CIDH). Hay supuestos excepcionales de diferimiento de admisibilidad al fondo; no toda actuación exige dos informes separados.",section:'#recorrido',related:['admisibilidad','competencia','fondo','archivo-peticion'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'archivo-peticion',label:'Archivo de una petición',aliases:['archivo del expediente','archivar una petición'],category:'Decisiones y documentos',definition:'Decisión de la CIDH de cerrar el trámite de una petición o caso en los supuestos y con las garantías previstas en su Reglamento. El archivo no equivale a una sentencia de fondo de la Corte ni a una declaración judicial sobre responsabilidad estatal.',use:'Consulta el acto de archivo y su fundamento; no infieras sus motivos solo por el estado del expediente.',section:'#comision',related:['peticion','admisibilidad','fondo','cidh'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'posicion-peticionario-sometimiento',label:'Posición del peticionario sobre el sometimiento',aliases:['un mes para opinar','artículo 44.3 del Reglamento CIDH','posición sobre el envío a la Corte'],category:'Plazos y escritos',definition:'En los casos previstos por el artículo 44.3 del Reglamento, al notificar al peticionario el informe preliminar la CIDH le da un mes para expresar su posición sobre el posible sometimiento. Si desea que el caso sea enviado, debe aportar los elementos que exige el artículo 44.3.',use:'Este mes corre para la posición del peticionario y no sustituye ni desplaza el período de tres meses del artículo 51.1.',section:'#reloj',related:['informe-preliminar','periodo-articulo-51','sometimiento','peticionario'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'criterios-sometimiento',label:'Criterios para someter un caso a la Corte',aliases:['criterios de sometimiento','artículo 45 del Reglamento CIDH'],category:'Etapas y argumentos',definition:'La CIDH considera los criterios reglamentarios para decidir si somete un caso: la posición del peticionario, la naturaleza y gravedad de la violación, la necesidad de desarrollar o aclarar la jurisprudencia y el eventual efecto de la decisión en los ordenamientos jurídicos de los Estados miembros.',use:'La posición del peticionario es relevante, pero no equivale a una decisión suya de presentar el caso ante la Corte.',section:'#recorrido',related:['posicion-peticionario-sometimiento','sometimiento','cidh','corteidh'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'escrito-sometimiento',label:'Escrito de sometimiento del caso',aliases:['sometimiento del caso ante la Corte','presentación del caso por la Comisión'],category:'Etapas y documentos',definition:'Acto procesal por el que la Comisión somete un caso a la Corte y presenta el informe correspondiente y los fundamentos de su posición, de acuerdo con la Convención y el Reglamento de la Corte. Inicia la fase contenciosa ante el Tribunal y no es el ESAP de las presuntas víctimas.',use:'Separa el envío del caso por la CIDH, la notificación de la Corte y el ESAP posterior.',section:'#recorrido',related:['sometimiento','cidh','corteidh','esap','notificacion'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'agente-estado',label:'Agente del Estado',aliases:['agentes estatales ante la Corte','representante del Estado','acreditación de agentes'],category:'Personas y roles',definition:'Persona acreditada para representar al Estado en el procedimiento ante la Corte. La acreditación, sus datos y eventuales cambios se rigen por el Reglamento del Tribunal.',use:'Distingue la representación estatal de las presuntas víctimas y de la participación de la CIDH.',section:'#recorrido',related:['corteidh','contestacion','representante','notificacion'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'plazo',label:'Plazo',aliases:['término','tiempo para actuar','fecha límite'],category:'Plazos y escritos',definition:'Período que una norma o decisión concede para realizar una actuación. Para calcularlo hay que identificar el acto inicial, su fecha, la unidad de cómputo y cualquier regla especial aplicable.',use:'No uses la duración aislada: vincula cada plazo con su actuación, órgano y fuente.',section:'#reloj',related:['plazo-procesal','notificacion','traslado','computo-plazos-cidh'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'plazo-procesal',label:'Plazo procesal',aliases:['plazos procesales','término procesal','vencimiento'],category:'Plazos y escritos',definition:'Período fijado por un tratado, reglamento, decisión o comunicación procesal para realizar una actuación. Su inicio y cómputo dependen de la regla aplicable, la fecha de notificación o traslado y las condiciones del expediente.',use:'Antes de contar, identifica quién debe actuar, qué acto activa el plazo y qué norma o decisión fija su duración.',section:'#reloj',related:['plazo','notificacion','traslado','computo-plazos-cidh','prorroga-y-suspension'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'prorroga-y-suspension',label:'Prórroga y suspensión de un plazo',aliases:['extensión del plazo','suspender un plazo','prórroga automática'],category:'Plazos y escritos',definition:'Prórroga es la ampliación de un plazo; suspensión es la detención temporal de su cómputo o curso, conforme a la norma o decisión aplicable. No son intercambiables. Para el período del artículo 51.1, el artículo 46 del Reglamento de la CIDH regula una posible suspensión a petición estatal y bajo condiciones; no establece una prórroga automática.',use:"En CIDH, art. 30.3: prórrogas fundadas hasta un máximo total de cuatro meses desde la primera solicitud de información al Estado. Art. 37.2: máximo total de seis meses desde la primera solicitud de observaciones a cada parte. Son límites totales, no meses adicionales. La suspensión del art. 46 es otra figura.",section:'#reloj',related:['plazo-procesal','suspension-articulo-51','periodo-articulo-51','computo-plazos-cidh'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'dias-corridos',label:'Días corridos',aliases:['días naturales','días calendario'],category:'Plazos y escritos',definition:'Días consecutivos del calendario, incluidos sábados, domingos y festivos. La Resolución 4/26 de la CIDH aclara que los plazos expresados en días se cuentan de este modo y regula el vencimiento en día inhábil.',use:'Aplica esta definición dentro del ámbito de la Resolución 4/26 y verifica si otra regla especial dispone algo distinto.',section:'#reloj',related:['computo-plazos-cidh','plazo-procesal','dia-inhabil'],source:'https://www.oas.org/es/cidh/decisiones/pdf/2026/res-4-26.pdf'},
  {id:'dia-inhabil',label:'Día inhábil',aliases:['día no laborable','día no hábil'],category:'Plazos y escritos',definition:'Día en que la oficina o autoridad procesal no realiza actividades ordinarias conforme a su calendario aplicable. La consecuencia para el vencimiento depende de la regla concreta; la Resolución 4/26 de la CIDH traslada ciertos vencimientos al siguiente día hábil.',use:'No supongas que los calendarios de Washington, la Corte y los tribunales nacionales coinciden.',section:'#reloj',related:['dias-corridos','computo-plazos-cidh','plazo-procesal'],source:'https://www.oas.org/es/cidh/decisiones/pdf/2026/res-4-26.pdf'},
  {id:'plazo-improrrogable',label:'Plazo improrrogable',aliases:['plazo no prorrogable','plazo que no admite prórroga'],category:'Plazos y escritos',definition:'Plazo que la norma califica como no susceptible de ampliación. Debe leerse en su contexto exacto y no confundirse con los plazos que la autoridad puede fijar o ampliar conforme a otra disposición.',use:'La ficha individual del plazo y el reglamento vigente prevalecen sobre una regla general del reloj didáctico.',section:'#reloj',related:['plazo-procesal','prorroga-y-suspension','esap','contestacion'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'resolucion-supervision',label:'Resolución de supervisión de cumplimiento',aliases:['resolución de cumplimiento','resolución de supervisión','resolución posterior a la sentencia'],category:'Decisiones y documentos',definition:'Decisión de la Corte dictada durante la etapa de supervisión que evalúa información sobre el cumplimiento de las reparaciones y otras medidas ordenadas. No sustituye la sentencia ni significa por sí sola que todo el caso esté cumplido.',use:'Al leerla, identifica cada medida supervisada, la información recibida y el estado que la Corte declara para esa obligación.',section:'#seguimiento',related:['sentencia','reparaciones','supervision','cumplimiento-medidas'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'cumplimiento-medidas',label:'Cumplimiento de medidas ordenadas',aliases:['cumplimiento de reparaciones','cumplimiento de sentencia'],category:'Decisiones y documentos',definition:'Ejecución de las medidas dispuestas por la Corte en una sentencia, que puede requerir actuaciones distintas y plazos diferentes. La Corte mantiene la competencia de supervisión en los términos de la Convención hasta que se cumpla lo ordenado.',use:'Revisa cada punto resolutivo por separado; un avance parcial no equivale al cumplimiento integral.',section:'#seguimiento',related:['supervision','resolucion-supervision','reparaciones','sentencia'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'objecion-declarantes',label:'Objeción a una declaración',aliases:['objeciones a declarantes','objeción de testigo','objeción de perito'],category:'Prueba y decisión',definition:'Planteamiento procesal sobre la admisibilidad, pertinencia u otro aspecto de una declaración o de quien declara, conforme al objeto y las reglas de prueba aplicables. La decisión corresponde al órgano competente.',use:'Explica qué parte de la declaración se cuestiona, por qué y qué regla sustenta la objeción.',section:'#recorrido',related:['prueba','testigo','perito','audiencia','recusacion'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'recusacion',label:'Recusación',aliases:['recusar a una persona juzgadora','recusación de juez'],category:'Prueba y decisión',definition:"Solicitud fundada para apartar a una persona de una intervención por una causal aplicable. En el procedimiento probatorio de la Corte, el artículo 48 regula específicamente la recusación de peritos; no debe confundirse con las objeciones a testigos del artículo 47 ni con los impedimentos y excusas de jueces del artículo 21.",use:"Para peritos, identifica la causal del artículo 48.1 y los diez días desde la recepción de la lista definitiva que confirma su ofrecimiento (art. 48.2). La Presidencia da traslado al perito y la Corte o su Presidencia decide.",section:"#recorrido?paso=16",related:['objecion-declarantes','corteidh','plazo-procesal'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'interpretacion-sentencia',label:'Solicitud de interpretación de sentencia',aliases:['interpretación del fallo','aclaración del sentido de la sentencia','artículo 67 CADH'],category:'Decisiones y documentos',definition:'Solicitud dirigida a aclarar el sentido o alcance de una sentencia de la Corte, presentada por quienes están legitimados dentro de los 90 días desde la notificación, conforme al artículo 67 CADH y al Reglamento del Tribunal. No es una apelación ni permite reabrir libremente el fondo.',use:'Identifica el punto cuyo sentido o alcance es dudoso y separa la interpretación de una impugnación de la decisión.',section:'#recorrido',related:['sentencia','plazo-procesal','corteidh'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'costas',label:'Costas',aliases:['costas procesales','reembolso de gastos del litigio'],category:'Prueba y decisión',definition:'Gastos razonables asociados al procedimiento que pueden ser considerados en la decisión de reparaciones, de acuerdo con los hechos, la prueba y las reglas de la Corte. No equivalen automáticamente a una indemnización por daño.',use:'Las pretensiones sobre costas deben sustentarse y presentarse en la fase procesal correspondiente.',section:'#recorrido',related:['reparaciones','esap','contestacion','sentencia'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'garantia-no-repeticion',label:'Garantías de no repetición',aliases:['garantía de no repetición','medidas para que no se repita'],category:'Prueba y decisión',definition:'Medidas de reparación dirigidas a reducir el riesgo de que vuelvan a ocurrir violaciones similares, según lo que la Corte determine en el caso. Su contenido depende de los hechos probados, la obligación incumplida y las circunstancias.',use:'No son una fórmula automática; relaciónalas con la causa de la violación y con lo ordenado en la sentencia.',section:'#recorrido',related:['reparaciones','sentencia','supervision','cumplimiento-medidas'],source:'https://www.corteidh.or.cr/docs/casos/articulos/seriec_4_esp.pdf'},
  {id:'peticion-vs-caso',label:'Petición y caso ante la CIDH',aliases:['diferencia entre petición y caso','registro de caso'],category:'Etapas y conceptos',definition:"La petición inicia el trámite ante la CIDH. Ordinariamente, al adoptar un informe de admisibilidad se registra como caso y se abre el fondo. Excepcionalmente puede diferirse la admisibilidad al debate y decisión sobre fondo (arts. 30.7 y 36.4 Reglamento CIDH). El registro como caso no declara responsabilidad.",use:'Al leer una ficha, identifica si está en revisión inicial, fue declarada admisible, está en fondo o fue sometida a la Corte.',section:'#recorrido',related:['peticion','informe-admisibilidad','fondo','sometimiento'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'presidencia-corte',label:'Presidencia de la Corte',aliases:['Presidente de la Corte','Presidenta de la Corte','Presidencia del Tribunal'],category:'Personas y roles',definition:'Autoridad de la Corte con funciones procesales previstas en su Estatuto y Reglamento, como dirigir aspectos del procedimiento y adoptar decisiones dentro de sus atribuciones. No reemplaza al pleno del Tribunal en las decisiones que corresponden a la Corte.',use:'Al revisar una orden, identifica si la dicta la Presidencia o la Corte y cuál norma atribuye esa actuación.',section:'#corte',related:['corteidh','audiencia','plazo-procesal','prueba'],source:'https://www.corteidh.or.cr/reglamento.cfm?lang=es'},
  {id:'observaciones-escritas',label:'Observaciones escritas',aliases:['observaciones de fondo','observaciones de las partes','respuesta escrita'],category:'Etapas y documentos',definition:'Escrito mediante el cual una parte responde a argumentos, hechos o documentos dentro de la etapa y el plazo fijados por la CIDH o la Corte. Su objeto depende de la comunicación que lo solicita; no todos los traslados abren el mismo tipo de observaciones.',use:'Anota quién debe responder, sobre qué materia y desde qué acto empieza el plazo.',section:'#recorrido',related:['traslado','notificacion','plazo-procesal','fondo','contestacion'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'recomendaciones-vs-reparaciones',label:'Recomendaciones y reparaciones: diferencia',aliases:['recomendaciones de la CIDH y reparaciones de la Corte','recomendación o reparación'],category:'Decisiones y documentos',definition:'Las recomendaciones aparecen en informes de la CIDH e indican medidas que la Comisión propone al Estado. Las reparaciones son medidas que la Corte puede ordenar en una sentencia contenciosa. Cambian el órgano, el documento, la etapa y el fundamento jurídico.',use:'En seguimiento, lee primero si el expediente es de la CIDH o de la Corte y qué acto sirve de referencia.',section:'#seguimiento',related:['recomendaciones','reparaciones','informe-preliminar','sentencia','supervision'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'informe-articulo-50',label:'Informe del artículo 50 de la Convención',aliases:['informe art. 50 CADH','informe preliminar de fondo artículo 50'],category:'Decisiones y documentos',definition:'Informe de la CIDH previsto en el artículo 50 de la Convención Americana tras el examen de fondo. Puede exponer hechos, conclusiones y recomendaciones; la transmisión a los Estados abre el período del artículo 51.1. El Reglamento desarrolla el informe preliminar y la ruta posterior.',use:'No lo confundas con el informe definitivo posterior, con el informe de solución amistosa ni con una sentencia.',section:'#recorrido',related:['informe-fondo','informe-preliminar','recomendaciones','periodo-articulo-51','informe-definitivo'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'publicacion-informe-cidh',label:'Publicación de un informe de la CIDH',aliases:['publicación del informe definitivo','publicar informe de fondo'],category:'Decisiones y documentos',definition:'La publicación depende del tipo de informe y de las reglas aplicables. Para el informe definitivo posterior al período del artículo 51, el artículo 47 del Reglamento prevé que la Comisión valore la información de cumplimiento y decida sobre su publicación por mayoría absoluta.',use:'No asumas que transmisión al Estado, notificación a las partes y publicación son el mismo acto.',section:'#seguimiento',related:['informe-preliminar','informe-definitivo','recomendaciones','notificacion'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'transmision-informe-preliminar',label:'Transmisión del informe preliminar al Estado',aliases:['remisión del informe preliminar','fecha de transmisión del informe artículo 50','notificación del informe preliminar al Estado'],category:'Etapas y documentos',definition:'Comunicación formal por la que la CIDH remite al Estado el informe preliminar del artículo 50. Para el artículo 51.1 de la Convención, esa transmisión a los Estados es el hito que inicia el período de tres meses. La notificación que recibe el peticionario activa una oportunidad separada para presentar su posición.',use:'Registra como fechas distintas la transmisión al Estado y la notificación al peticionario.',section:'#recorrido',related:['informe-preliminar','informe-articulo-50','periodo-articulo-51','posicion-peticionario-sometimiento','notificacion'],source:'https://www.oas.org/es/cidh/mandato/basicos/convencion.asp'},
  {id:'respuesta-inicial-estado',label:'Respuesta inicial del Estado ante la CIDH',aliases:['respuesta estatal inicial','respuesta a la petición','contestación inicial CIDH'],category:'Etapas y documentos',definition:'Observaciones que el Estado puede presentar cuando la CIDH le transmite partes pertinentes de una petición para recabar información. El artículo 30 del Reglamento establece el plazo correspondiente y permite que la Comisión solicite información adicional. Este intercambio inicial no decide la admisibilidad ni el fondo.',use:'Distingue esta respuesta de la contestación del Estado ante la Corte y de su respuesta posterior sobre el fondo.',section:'#recorrido',related:['traslado','peticion','notificacion','contestacion','admisibilidad'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'observaciones-de-fondo',label:'Observaciones sobre el fondo',aliases:['observaciones de fondo del peticionario','observaciones de fondo del Estado','respuesta estatal de fondo'],category:'Etapas y documentos',definition:'Escritos en los que las partes presentan argumentos e información sobre los hechos, las obligaciones internacionales y la posible responsabilidad estatal durante la etapa de fondo ante la CIDH. La Comisión fija el trámite y los plazos correspondientes; las observaciones no son todavía el informe de fondo.',use:'Identifica quién presenta cada escrito y separa sus alegaciones de las conclusiones que adoptará la Comisión.',section:'#recorrido',related:['fondo','observaciones-escritas','informe-fondo','obligacion-internacional','atribucion-estatal'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'informe-cumplimiento-estado',label:'Información del Estado sobre cumplimiento',aliases:['informe de cumplimiento estatal','respuesta a las recomendaciones','información estatal de cumplimiento'],category:'Decisiones y documentos',definition:'Información que el Estado presenta sobre las medidas que adoptó para cumplir recomendaciones o reparaciones. La actuación, el plazo y el órgano que la recibe dependen de si se trata de recomendaciones de la CIDH o de medidas ordenadas por la Corte.',use:'No llames “cumplida” a una medida solo porque el Estado informe que actuó: identifica quién evalúa y qué decisión lo confirma.',section:'#seguimiento',related:['recomendaciones','reparaciones','informe-definitivo','supervision','cumplimiento-medidas'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'subsanacion-sometimiento',label:'Subsanación del sometimiento del caso',aliases:['subsanar requisitos del caso','corrección del sometimiento','artículo 38 Reglamento Corte'],category:'Etapas y documentos',definition:'Si en el examen preliminar del sometimiento la Presidencia de la Corte observa que falta un requisito fundamental, solicita que se corrija dentro del plazo de 20 días previsto por el artículo 38 del Reglamento. Es una revisión formal inicial, no una decisión sobre el fondo ni una ampliación general de los demás plazos.',use:'Colócala después del sometimiento y antes de la notificación formal del caso.',section:'#recorrido',related:['escrito-sometimiento','sometimiento','presidencia-corte','notificacion','plazo-procesal'],source:'https://www.oas.org/es/cidh/mandato/Basicos/reglamentoCorte.asp'},
  {id:'defensor-interamericano',label:'Defensor Interamericano',aliases:['defensora interamericana','Defensa Pública Interamericana','representación de oficio ante la Corte'],category:'Personas y roles',definition:'Abogado o abogada que el Tribunal puede designar de oficio para representar durante el trámite a presuntas víctimas que no cuentan con representación legal debidamente acreditada, conforme al artículo 37 del Reglamento de la Corte.',use:'No es agente del Estado ni representante de la CIDH; su función es asistir a las presuntas víctimas en el proceso ante la Corte.',section:'#corte',related:['victima','representante','agente-estado','corteidh','notificacion'],source:'https://www.oas.org/es/cidh/mandato/Basicos/reglamentoCorte.asp'},
  {id:'formas-de-terminacion-cidh',label:'Formas de cierre del trámite ante la CIDH',aliases:['cómo puede terminar un caso CIDH','resolución posible de una petición','decisiones que cierran un caso'],category:'Decisiones y documentos',definition:"Deben distinguirse la inadmisibilidad, el archivo por sus causales, el informe de solución amistosa y el informe de fondo que concluye que no hubo violación. Cuando se establecen violaciones, el informe preliminar con recomendaciones es un acto intermedio: puede seguir el sometimiento o la ruta del informe definitivo y publicación, bajo las condiciones aplicables.",use:"Consulta los artículos 36, 40, 42 y 44–48 del Reglamento CIDH. No confundas un documento intermedio con un acto que termina la vía correspondiente.",section:'#comision',related:['archivo-peticion','solucion-amistosa','informe-fondo','informe-definitivo','sometimiento','sentencia'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'resolucion-informe-sentencia',label:'Resolución, informe y sentencia',aliases:['diferencia entre resolución y sentencia','acto de la CIDH','decisión de la Corte'],category:'Decisiones y documentos',definition:'“Resolución” puede nombrar distintos actos procesales y no identifica por sí sola una decisión final. La CIDH emite informes y puede aprobar resoluciones en sus mecanismos; la Corte dicta sentencias en casos contenciosos y resoluciones en actuaciones como supervisión. Hay que leer órgano, tipo de acto, etapa y parte resolutiva.',use:'No concluyas que un caso fue decidido en cuanto al fondo solo porque una fuente menciona una “resolución”.',section:'#jurisprudencia',related:['cidh','corteidh','informe-fondo','informe-definitivo','sentencia','resolucion-supervision'],source:'https://www.oas.org/es/cidh/mandato/Basicos/reglamentoCorte.asp'}
];

// Ampliación editorial de la ruta de fondo: distingue los actos, sus destinatarios,
// los plazos y los hitos que no deben confundirse. Fuentes primarias enlazadas.
{
  const entries = window.RI_GLOSARIO;
  const byId = new Map(entries.map(item => [item.id, item]));
  const enrich = (id, update) => Object.assign(byId.get(id), update);

  enrich('informe-fondo', {
    aliases: [...new Set([...byId.get('informe-fondo').aliases, 'informe sobre el fondo', 'decisión de fondo de la CIDH'])],
    definition: '“Informe sobre el fondo” nombra el examen y la decisión de la CIDH sobre los hechos, las pruebas y las obligaciones aplicables (Reglamento, art. 43). Si la Comisión concluye que no hubo violación, lo expresa en su informe y lo transmite a las partes. Si establece una o más violaciones, el artículo 44.2 del Reglamento prevé un informe preliminar con proposiciones y recomendaciones que se transmite al Estado; ese informe corresponde al previsto en el artículo 50 de la Convención Americana. No es una sentencia de la Corte.',
    use: 'Sigue esta secuencia sin saltos: deliberación sobre el fondo → conclusión de la CIDH → si hay violaciones, informe preliminar art. 50 y transmisión al Estado → período art. 51.1. Si no hubo violación, la CIDH transmite y publica el informe de fondo conforme al art. 44.1 del Reglamento.',
    related: [...new Set([...byId.get('informe-fondo').related, 'informe-sobre-fondo-cidh', 'informe-articulo-50', 'transmision-informe-preliminar', 'informe-definitivo'])]
  });
  enrich('informe-preliminar', {
    aliases: [...new Set([...byId.get('informe-preliminar').aliases, 'informe preliminar artículo 50 CADH', 'informe confidencial artículo 50', 'informe con recomendaciones artículo 50'])],
    definition: 'Cuando, tras deliberar sobre el fondo, la CIDH establece una o más violaciones, prepara el informe preliminar con las proposiciones y recomendaciones que estime pertinentes y lo transmite al Estado (Reglamento CIDH, art. 44.2). Es el informe previsto en el artículo 50 de la Convención Americana. El Estado debe informar, dentro del plazo que fije la CIDH, las medidas adoptadas para cumplir las recomendaciones; no puede publicar el informe hasta que la Comisión decida al respecto. Este acto no es el informe definitivo posterior ni una sentencia.',
    use: 'Anota tres hitos separados: adopción del informe, transmisión al Estado y notificación al peticionario. La transmisión al Estado inicia el período convencional del artículo 51.1; la notificación al peticionario abre, en los casos contemplados, un mes para presentar su posición sobre un posible sometimiento (Reglamento, art. 44.3).',
    related: [...new Set([...byId.get('informe-preliminar').related, 'informe-sobre-fondo-cidh', 'periodo-recomendaciones-estado', 'posicion-peticionario-sometimiento', 'notificacion-peticionario-informe'])]
  });
  enrich('informe-articulo-50', {
    aliases: [...new Set([...byId.get('informe-articulo-50').aliases, 'informe del artículo 50 CADH', 'informe confidencial artículo 50'])],
    definition: 'Es el informe de la CIDH del artículo 50 de la Convención Americana. En la ruta reglamentaria, cuando la Comisión establece violaciones, el artículo 44.2 llama “informe preliminar” al documento que contiene las proposiciones y recomendaciones y se transmite al Estado. El artículo 50 dispone que, si no hay solución dentro del plazo fijado, la Comisión puede optar por someter el caso a la Corte (si existe competencia) o continuar a la etapa del artículo 51. La transmisión, el sometimiento y la publicación son actos distintos.',
    use: 'No leas “artículo 50” como si fuera el informe definitivo del artículo 51. Para ubicar el expediente, busca quién recibió el informe, en qué fecha y si después hubo sometimiento o publicación.',
    related: [...new Set([...byId.get('informe-articulo-50').related, 'informe-sobre-fondo-cidh', 'periodo-recomendaciones-estado', 'remision-caso-corte'])]
  });
  enrich('periodo-articulo-51', {
    aliases: [...new Set([...byId.get('periodo-articulo-51').aliases, 'tres meses desde transmisión del informe preliminar', 'plazo convencional artículo 51.1'])],
    definition: 'El período de tres meses del artículo 51.1 de la Convención Americana se cuenta desde la remisión a los Estados del informe de la Comisión previsto en el artículo 50. Dentro de ese lapso el asunto puede solucionarse o someterse a la Corte por la Comisión o por el Estado interesado que haya aceptado su competencia. Si ninguna alternativa ocurre, la Comisión puede emitir el informe del artículo 51. No es el plazo de un mes concedido al peticionario ni un plazo para que el Estado responda a las recomendaciones.',
    use: 'Construye la cronología desde la constancia de transmisión del informe a los Estados. Registra aparte la fecha de notificación al peticionario y el plazo que la CIDH fije al Estado para informar sobre cumplimiento: tienen destinatarios y funciones diferentes.',
    related: [...new Set([...byId.get('periodo-articulo-51').related, 'periodo-recomendaciones-estado', 'notificacion-peticionario-informe', 'remision-caso-corte', 'solicitud-suspension-articulo-51'])]
  });
  enrich('informe-definitivo', {
    aliases: [...new Set([...byId.get('informe-definitivo').aliases, 'informe del artículo 51 de la Convención', 'informe posterior a los tres meses'])],
    definition: 'El Reglamento CIDH, artículo 47.1, permite que la Comisión emita, por mayoría absoluta, un informe definitivo con su opinión, conclusiones finales y recomendaciones si pasan tres meses desde la transmisión del informe preliminar sin solución amistosa ni sometimiento a la Corte, cuando esta tenga competencia. No se emite automáticamente al vencer el plazo: la norma dice que la Comisión “podrá” emitirlo. Luego lo transmite a las partes, fija un plazo para información sobre cumplimiento y decide sobre su publicación, también por mayoría absoluta (art. 47.2–3).',
    use: 'Verifica sucesivamente: fecha de transmisión → si hubo solución o sometimiento → si la CIDH adoptó el informe → plazo de información de cumplimiento → decisión de publicación. El vencimiento de tres meses, por sí solo, no prueba que exista un informe definitivo.',
    related: [...new Set([...byId.get('informe-definitivo').related, 'mayoria-absoluta-cidh', 'publicacion-informe-cidh', 'informe-cumplimiento-estado'])]
  });
  enrich('suspension-articulo-51', {
    aliases: [...new Set([...byId.get('suspension-articulo-51').aliases, 'suspensión solicitada por el Estado', 'extensión artículo 51.1'])],
    definition: 'La CIDH puede considerar suspender el período del artículo 51.1 únicamente a solicitud del Estado y si se cumplen las condiciones del artículo 46 de su Reglamento: acciones concretas e idóneas que demuestren voluntad y capacidad de implementar las recomendaciones, y aceptación expresa e irrevocable de la suspensión junto con la renuncia a oponer una excepción preliminar por incumplimiento del plazo si el asunto llega a la Corte. La Comisión fija el período considerando, entre otros factores, complejidad, medidas adoptadas y posición del peticionario.',
    use: 'No hay prórroga automática ni basta con pedir más tiempo. Registra solicitud, evidencia de cumplimiento, aceptación y renuncia expresas, decisión de la CIDH, duración y condiciones. La suspensión depende de la consideración de la Comisión.',
    related: [...new Set([...byId.get('suspension-articulo-51').related, 'solicitud-suspension-articulo-51', 'periodo-articulo-51', 'informe-cumplimiento-estado'])]
  });
  enrich('recomendaciones', {
    definition: 'Son medidas que la CIDH formula en un informe de fondo si establece una o más violaciones. En la ruta del artículo 50, se incluyen en el informe preliminar transmitido al Estado; la Comisión fija un plazo para que informe qué medidas adoptó (Reglamento, art. 44.2). La CIDH puede evaluar el cumplimiento y dar seguimiento. Las recomendaciones no son una sentencia ni deben confundirse con reparaciones ordenadas por la Corte.',
    use: 'Al estudiar cada recomendación, identifica la conducta solicitada, la autoridad que podría ejecutarla, los indicadores de cumplimiento, la respuesta estatal y la evaluación de la CIDH. La fuerza y el alcance jurídico de las recomendaciones han sido objeto de interpretación jurisprudencial; consulta el caso citado y no las describas como sentencia ejecutable.',
    related: [...new Set([...byId.get('recomendaciones').related, 'periodo-recomendaciones-estado', 'informe-cumplimiento-estado', 'deber-buena-fe-recomendaciones'])]
  });

  entries.push(
    {id:'informe-sobre-fondo-cidh',label:'Informe sobre el fondo de la CIDH',aliases:['decisión sobre el fondo','informe de fondo de la Comisión','deliberación de fondo'],category:'Decisiones y documentos',definition:'Es el resultado del examen de los alegatos, pruebas y demás información de un caso por la CIDH (Reglamento, art. 43). El artículo 44 distingue dos resultados: si no hubo violación, la Comisión lo expresa en el informe que transmite a las partes y publica; si hubo una o más violaciones, prepara el informe preliminar del artículo 50 con recomendaciones y lo transmite al Estado. “Informe sobre el fondo” puede nombrar la decisión sustantiva en general; “informe preliminar” identifica el acto de la ruta del artículo 50.',use:'Pregunta primero qué concluyó la CIDH. La secuencia y publicidad posterior cambian según la conclusión; no conviertas todos los resultados en una sola ficha llamada “informe de fondo”.',section:'#recorrido',related:['informe-fondo','informe-preliminar','informe-articulo-50','informe-definitivo','recomendaciones'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
    {id:'periodo-recomendaciones-estado',label:'Plazo para informar sobre recomendaciones',aliases:['plazo de cumplimiento de recomendaciones','plazo que fija la CIDH al Estado','respuesta estatal a recomendaciones'],category:'Plazos y escritos',definition:'Al transmitir el informe preliminar, la CIDH fija un plazo para que el Estado informe las medidas que adoptó para cumplir las recomendaciones (Reglamento CIDH, art. 44.2). La norma no establece aquí un único número de meses aplicable a todos los casos: hay que consultar la comunicación y el plazo concretos fijados por la Comisión. Este plazo es distinto de los tres meses del artículo 51.1, que se cuentan desde la transmisión del informe a los Estados, y del mes que puede tener el peticionario para expresar su posición.',use:'No sustituyas la fecha o duración fijada en la comunicación por una cifra genérica. Anota destinatario, fecha de inicio indicada y fecha límite; verifica si hubo una decisión posterior que cambió el calendario.',section:'#reloj',related:['informe-preliminar','recomendaciones','informe-cumplimiento-estado','periodo-articulo-51','posicion-peticionario-sometimiento'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
    {id:'notificacion-peticionario-informe',label:'Notificación al peticionario del informe preliminar',aliases:['notificación al peticionario artículo 44.3','aviso del informe preliminar al peticionario','mes para posición del peticionario'],category:'Etapas y documentos',definition:'La CIDH notifica al peticionario la adopción del informe preliminar y su transmisión al Estado (Reglamento, art. 44.3). En los casos de Estados parte de la Convención Americana que hayan aceptado la jurisdicción contenciosa de la Corte, esa notificación debe ofrecer al peticionario un mes para presentar su posición sobre el posible sometimiento. Si pide que se remita, presenta la posición de la víctima o familiares cuando sean distintos, sus fundamentos y pretensiones de reparaciones y costas.',use:'El mes empieza con la oportunidad notificada al peticionario; no es el período convencional de tres meses del artículo 51.1. Comprueba también si el Estado aceptó la competencia contenciosa de la Corte.',section:'#recorrido',related:['informe-preliminar','posicion-peticionario-sometimiento','periodo-articulo-51','notificacion','sometimiento'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
    {id:'remision-caso-corte',label:'Remisión del caso de la CIDH a la Corte',aliases:['envío del caso a la Corte','remisión del informe artículo 50 a la Corte','transmisión del expediente a la Corte'],category:'Etapas y documentos',definition:'Cuando la CIDH decide someter el caso, remite a la Corte el informe del artículo 50, copia del expediente (excepto documentos de trabajo interno) y otros elementos útiles. La nota de envío puede explicar el cumplimiento de recomendaciones y las razones del sometimiento. Una vez sometido, la CIDH hace público el informe aprobado conforme al artículo 50 (Reglamento CIDH, arts. 45 y 74). El sometimiento abre la fase ante un órgano distinto; no equivale todavía a una sentencia.',use:'Verifica competencia de la Corte respecto del Estado, decisión de sometimiento, fecha de recepción por la Corte y documentos efectivamente remitidos. Después comienza el trámite judicial según el Reglamento de la Corte.',section:'#recorrido?paso=10',related:['sometimiento','informe-articulo-50','informe-preliminar','recomendaciones','corteidh','esap','informe-definitivo'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
    {id:'mayoria-absoluta-cidh',label:'Mayoría absoluta de la CIDH',aliases:['mayoría absoluta de votos','mayoría absoluta de comisionados','votación artículo 47 CIDH'],category:'Siglas y conceptos',definition:'Regla de votación que exige más de la mitad de la integración de la Comisión, conforme al artículo 18 de su Reglamento; no debe confundirse con más de la mitad de quienes asisten si ambas cantidades difieren. El Reglamento la exige para determinadas decisiones, entre ellas emitir el informe definitivo del artículo 47 y decidir sobre su publicación.',use:'Al leer una decisión, identifica la regla de votación aplicable y la composición relevante del órgano. No infieras el resultado de una votación a partir del texto del informe solamente.',section:'#comision',related:['cidh','informe-definitivo','publicacion-informe-cidh'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
    {id:'deber-buena-fe-recomendaciones',label:'Cumplimiento de buena fe de recomendaciones',aliases:['fuerza de las recomendaciones CIDH','obligación de cumplir recomendaciones','Loayza Tamayo recomendaciones'],category:'Responsabilidad internacional',definition:'La Corte Interamericana ha considerado que los Estados deben realizar sus mejores esfuerzos para aplicar las recomendaciones de la CIDH, como parte de sus deberes de buena fe y de cumplir la Convención. Esto no convierte el informe de la Comisión en una sentencia de la Corte ni permite atribuirle automáticamente el mismo régimen de ejecución de una sentencia. La cuestión debe exponerse con el alcance exacto de la jurisprudencia aplicable.',use:'Al citar “Loayza Tamayo vs. Perú”, separa la interpretación sobre buena fe y mejores esfuerzos de la naturaleza procesal del informe y del régimen de cumplimiento de una sentencia.',section:'#jurisprudencia',related:['recomendaciones','informe-preliminar','sentencia','cumplimiento-medidas'],source:'https://www.corteidh.or.cr/docs/casos/articulos/seriec_33_esp.pdf'},
    {id:'solicitud-suspension-articulo-51',label:'Solicitud estatal de suspensión del artículo 51.1',aliases:['pedir suspensión del plazo de tres meses','solicitud de extensión del artículo 51','prórroga para cumplir recomendaciones artículo 46'],category:'Plazos y escritos',definition:'Es la petición que presenta el Estado para que la CIDH considere suspender el período del artículo 51.1. Debe acompañarse de elementos que demuestren voluntad y capacidad de cumplir mediante acciones concretas e idóneas, además de una aceptación expresa e irrevocable de la suspensión y de la renuncia procesal prevista en el artículo 46.1.b del Reglamento. La solicitud por sí sola no altera el plazo: hace falta que la Comisión considere la suspensión y establezca sus condiciones.',use:'Distingue: plazo que la CIDH fijó para informar sobre recomendaciones; período de tres meses de la Convención; y posible suspensión del artículo 46. No los llames a todos “prórroga”.',section:'#reloj',related:['suspension-articulo-51','periodo-articulo-51','periodo-recomendaciones-estado','informe-cumplimiento-estado'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'}
  );
}

// Conceptos de transición y cierre para completar la ruta sin dar por supuestos
// los efectos de cada documento o respuesta.
window.RI_GLOSARIO.push(
  {id:'informe-solucion-amistosa-articulo-49',label:'Informe de solución amistosa (artículo 49)',aliases:['informe artículo 49 CADH','informe de acuerdo amistoso CIDH','informe de solución amistosa'],category:'Decisiones y documentos',definition:'Cuando se alcanza una solución amistosa conforme al artículo 48.1.f de la Convención, la CIDH redacta un informe que resume los hechos y la solución, lo transmite al peticionario y a los Estados parte y lo comunica al Secretario General para publicación (Convención, art. 49; Reglamento CIDH, art. 40). Este informe responde a un acuerdo consentido y no es el informe de fondo de los artículos 50–51.',simple:'Es el documento que formaliza una solución amistosa alcanzada con consentimiento. No es una sentencia ni el informe de fondo.',example:'Si las partes acuerdan medidas y la víctima presta su consentimiento, la CIDH puede aprobar el informe que describe ese acuerdo.',use:'Comprueba que hubo consentimiento y localiza el informe aprobado; no confundas una propuesta de acuerdo con una solución formalizada.',section:'#recorrido',related:['solucion-amistosa','informe-articulo-50','informe-sobre-fondo-cidh','informe-cumplimiento-estado'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'diferencia-articulo-51-1-2',label:'Diferencia entre los artículos 51.1 y 51.2',aliases:['qué pasa después de los tres meses','artículo 51.1 frente a 51.2','tres meses y plazo para medidas'],category:'Plazos y escritos',definition:'El artículo 51.1 establece el período de tres meses desde la remisión del informe a los Estados y las condiciones bajo las cuales la CIDH puede emitir su opinión y conclusiones. El artículo 51.2 regula un momento posterior: la Comisión formula recomendaciones y fija al Estado un plazo para tomar medidas. Son etapas sucesivas con hitos distintos, no un solo plazo de tres meses.',simple:'El 51.1 habla del período inicial de tres meses; el 51.2, del plazo posterior para que el Estado actúe.',example:'No uses la fecha de transmisión del informe como fecha límite automática de las medidas que más tarde ordene considerar la Comisión.',use:'Dibuja dos líneas temporales: transmisión → período de tres meses; después, informe y plazo concreto que fije la CIDH para tomar medidas.',section:'#reloj',related:['periodo-articulo-51','opinion-conclusiones-articulo-51','plazo-medidas-articulo-51-2','evaluacion-medidas-articulo-51'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
  {id:'respuesta-no-es-cumplimiento',label:'Respuesta estatal y cumplimiento: diferencia',aliases:['informar no significa cumplir','respuesta del Estado a las recomendaciones','cumplimiento efectivo de recomendaciones'],category:'Decisiones y documentos',definition:'Que el Estado presente información prueba que respondió, no necesariamente que adoptó todas las medidas recomendadas o que la CIDH las considere adecuadas. El Reglamento exige información y seguimiento; la Convención prevé que la Comisión valore la adecuación de las medidas en el momento que corresponda (arts. 47–48 Reglamento; 51.2–3 Convención).',simple:'Una respuesta describe lo que el Estado dice haber hecho. La Comisión aún debe evaluar si eso cumple la recomendación.',example:'El Estado entrega un informe y adjunta una ley; la CIDH puede analizar si esa ley aborda la medida recomendada y si se aplicó.',use:'Separa tres columnas: medida pedida, información presentada por el Estado y evaluación oficial de la CIDH.',section:'#seguimiento',related:['informe-cumplimiento-estado','recomendaciones','evaluacion-medidas-articulo-51','informe-definitivo'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'cumplimiento-parcial-recomendacion',label:'Cumplimiento parcial de una recomendación',aliases:['cumplió algunas recomendaciones','cumplimiento incompleto CIDH','avance parcial de medidas'],category:'Decisiones y documentos',definition:'Describe una situación en la que hay avances respecto de una recomendación, pero no se han acreditado todas sus acciones o resultados. La evaluación debe hacerse medida por medida y con la información disponible; no se debe convertir “hay avances” en “cumplimiento total” ni “incompleto” en “ninguna acción”.',simple:'Puede haber avances sin que la recomendación esté cumplida por completo.',example:'Se abre una investigación (avance), pero aún no hay decisión ni información sobre otras medidas solicitadas.',use:'Identifica qué componente se cumplió, cuál sigue pendiente, quién lo verificó y qué evidencia sustenta la clasificación.',section:'#seguimiento',related:['recomendaciones','informe-cumplimiento-estado','respuesta-no-es-cumplimiento','evaluacion-medidas-articulo-51'],source:'https://www.oas.org/es/cidh/informes/pdfs/2024/Directrices-generales-seguimiento-2daEdicion.pdf'},
  {id:'publicacion-por-sometimiento',label:'Publicación del informe al someter el caso',aliases:['cuándo se publica el informe artículo 50','publicación al enviar el caso a la Corte','informe artículo 50 público'],category:'Decisiones y documentos',definition:'Cuando la CIDH somete un caso a la Corte, el Reglamento dispone que hará público el informe aprobado conforme al artículo 50 de la Convención y la nota de envío (Reglamento CIDH, art. 74.3). Esta ruta de publicidad debe diferenciarse de la decisión posterior de publicar un informe definitivo bajo el artículo 47 del Reglamento y el artículo 51.3 de la Convención.',simple:'Si la Comisión envía el caso a la Corte, publica el informe del artículo 50 y la nota de envío.',example:'Busca la decisión de sometimiento y comprueba si junto al caso se difundieron el informe y la nota.',use:'La fecha de publicación puede seguir al sometimiento; no la uses como fecha de transmisión que inició el período de tres meses.',section:'#recorrido',related:['remision-caso-corte','informe-articulo-50','publicacion-informe-articulo-51','transmision-informe-preliminar'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'plazo-informacion-partes-informe-definitivo',label:'Plazo para informar tras el informe definitivo',aliases:['plazo de respuesta al informe definitivo','información de partes artículo 47.2','respuesta sobre recomendaciones informe artículo 51'],category:'Plazos y escritos',definition:'Después de transmitir el informe definitivo, la CIDH fija a las partes un plazo para presentar información sobre el cumplimiento de las recomendaciones (Reglamento CIDH, art. 47.2). No es automáticamente igual al período anterior de tres meses ni al plazo que se haya fijado en el informe preliminar.',simple:'Cuando se transmite el informe definitivo, la Comisión fija otro plazo para que las partes informen sobre cumplimiento.',example:'Consulta la carta de transmisión del informe definitivo para identificar el plazo concreto y quién debe responder.',use:'No recicles fechas de otras fases: anota el acto nuevo y el plazo específico fijado en esa comunicación.',section:'#reloj',related:['informe-definitivo','informe-cumplimiento-estado','periodo-articulo-51','periodo-recomendaciones-estado'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'documento-vigente-y-version',label:'Versión vigente del Reglamento',aliases:['qué reglamento aplicar','versión del reglamento CIDH','regla vigente al momento del trámite'],category:'Fuentes y método',definition:'Antes de aplicar un artículo procesal, comprueba el texto oficial y la versión temporal pertinente. Las reformas, resoluciones de interpretación y reglas transitorias pueden cambiar cómo se computa un plazo o qué procedimiento se aplica. Un resumen educativo ayuda a orientarse, pero no reemplaza la comunicación de la CIDH ni la norma vigente.',simple:'Comprueba que estás leyendo la regla y la versión que aplican a ese trámite.',example:'Si una ficha y una comunicación oficial parecen diferir, revisa fecha, norma citada y texto oficial antes de calcular.',use:'Registra enlace oficial, artículo, fecha de consulta y cualquier regla transitoria pertinente.',section:'#biblioteca',related:['plazo','plazo-procesal','computo-plazos-cidh','informe-preliminar'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
  {id:'fecha-de-transmision-informe',label:'Fecha de transmisión del informe',aliases:['desde cuándo cuentan los tres meses','fecha de remisión del informe a los Estados','inicio del período artículo 51'],category:'Plazos y escritos',definition:'Es la fecha en que el informe previsto en el artículo 50 se remite a los Estados interesados. La Convención utiliza esta remisión como hito para contar los tres meses del artículo 51.1. No es necesariamente el día en que se adoptó el informe, se notificó al peticionario o se publicó.',simple:'Para los tres meses del artículo 51, busca cuándo se envió el informe a los Estados.',example:'La CIDH puede adoptar el informe un día y notificar al peticionario y al Estado en días distintos; registra cada evento por separado.',use:'Usa la constancia de transmisión a los Estados, no una fecha aproximada deducida de otro aviso.',section:'#reloj',related:['transmision-informe-preliminar','periodo-articulo-51','notificacion-peticionario-informe','notificacion'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'}
);

// Resumen en lenguaje llano y ejemplos concretos para los conceptos que suelen
// confundirse al leer la ruta de la Comisión y la Corte.
{
  const byId = new Map(window.RI_GLOSARIO.map(item => [item.id, item]));
  const plain = (id, simple, example) => Object.assign(byId.get(id), {simple, example});
  plain('hecho','Qué ocurrió, cuándo y a quién. Un hecho todavía no dice si alguien incumplió la ley.','“La ambulancia llegó a las 18:00” es un hecho; “el Estado violó un derecho” es una conclusión jurídica.');
  plain('hecho-alegado','Es lo que una parte dice que pasó. La Comisión o la Corte aún deben evaluarlo.','La familia afirma que pidió protección tres veces. Esa afirmación es un hecho alegado mientras no se valore.');
  plain('hecho-probado','Es un hecho que el órgano considera demostrado con la información que examinó.','Un registro confirma la fecha de detención. Eso puede probar la fecha, pero no resuelve por sí solo si hubo una violación.');
  plain('peticion','Es el escrito que lleva una posible violación ante la Comisión. Presentarlo no significa que la Comisión ya haya aceptado el caso o declarado una violación.','Una organización presenta una petición en nombre de una persona y aporta fechas, decisiones y documentos.');
  plain('peticionario','Es quien presenta la petición. Puede ser una persona u organización distinta de la presunta víctima.','Una ONG puede presentar la petición; la persona afectada sigue siendo la presunta víctima.');
  plain('admisibilidad','Es la revisión de requisitos para decidir si la Comisión puede pasar a estudiar el fondo. No decide todavía quién tiene razón.','La Comisión revisa recursos internos, plazo, duplicidad y si los hechos podrían mostrar una violación.');
  plain('fondo','Es la etapa en que se examina qué pasó y qué significan jurídicamente los hechos y las pruebas.','La pregunta ya no es solo “¿se puede estudiar la petición?”, sino “¿los hechos probados incumplieron una obligación?”.');
  plain('informe-sobre-fondo-cidh','Es el resultado del análisis de la Comisión sobre los hechos y las normas. La ruta siguiente depende de si encontró o no una violación.','Si no encuentra violación, informa esa conclusión. Si encuentra una o más, prepara el informe preliminar y recomendaciones.');
  plain('informe-preliminar','Es el informe con recomendaciones que la Comisión transmite al Estado después de encontrar una o más violaciones.','La Comisión transmite el informe al Estado y fija un plazo para que informe qué medidas tomó.');
  plain('periodo-articulo-51','Es un período de tres meses que comienza con la transmisión del informe a los Estados. Durante ese período puede resolverse el asunto o someterse a la Corte.','No lo cuentes desde el día en que el peticionario recibió la notificación; ese es otro hito.');
  plain('periodo-recomendaciones-estado','Es el tiempo que la Comisión fija para que el Estado informe qué hizo frente a las recomendaciones. Debes leer la comunicación: no hay un número único para todos los casos.','El Estado recibe un informe con recomendaciones y una carta que indica la fecha límite de su respuesta.');
  plain('notificacion-peticionario-informe','Es el aviso al peticionario de que se adoptó el informe preliminar. En ciertos casos, con ese aviso se abre un mes para que exprese su posición sobre enviar el caso a la Corte.','Este mes corresponde al peticionario; no son los tres meses del artículo 51.1.');
  plain('recomendaciones','Son medidas que la Comisión pide considerar al Estado tras identificar violaciones. No son una sentencia de la Corte.','Una recomendación puede pedir investigar, reparar o cambiar una práctica; luego la Comisión revisa la información sobre su cumplimiento.');
  plain('suspension-articulo-51','La Comisión puede detener el curso del período de tres meses si el Estado lo solicita y cumple las condiciones del Reglamento. No ocurre automáticamente.','Una solicitud sin acciones concretas ni aceptación expresa de las condiciones no suspende por sí sola el período.');
  plain('informe-definitivo','Es un informe posterior que la Comisión puede emitir si se cumplen las condiciones de la Convención y su Reglamento. El vencimiento del plazo no lo crea automáticamente.','Primero se verifica transmisión y transcurso del período; después debe existir una decisión de la Comisión.');
  plain('remision-caso-corte','Es el envío formal del caso y el expediente de la Comisión a la Corte. El envío no es todavía una sentencia.','Después de la remisión, la Corte abre su propio trámite y notifica a quienes intervienen.');
  plain('sometimiento','Es la decisión procesal de llevar el caso ante la Corte cuando se reúnen las condiciones aplicables.','La Comisión debe comprobar, entre otros puntos, que la Corte puede conocer del caso.');
  plain('traslado','Es pasar un escrito o información a otra parte para que pueda conocerla y, cuando corresponda, responder.','La fecha del traslado puede iniciar un plazo; comprueba el escrito y la instrucción que lo acompaña.');
  plain('notificacion','Es el aviso formal de una decisión o actuación. Para calcular un plazo necesitas saber qué se notificó, a quién y cuándo.','La notificación al peticionario y la transmisión del informe a los Estados pueden ocurrir en fechas distintas.');
  plain('recomendaciones-vs-reparaciones','La Comisión formula recomendaciones en informes; la Corte puede ordenar reparaciones en una sentencia. Son actos de órganos y etapas diferentes.','Una petición de reparación en el ESAP no convierte las recomendaciones de la Comisión en reparaciones judiciales.');
  plain('resolucion-informe-sentencia','El nombre del documento no basta: identifica quién lo emitió, en qué etapa y qué decidió.','Una resolución de supervisión trata del cumplimiento; una sentencia decide el caso sometido a la Corte.');
  plain('solicitud-suspension-articulo-51','Es la petición del Estado para que la Comisión considere suspender el período. La solicitud no basta: hace falta la decisión de la CIDH.','Anota cuándo se pidió, qué pruebas de cumplimiento se presentaron y qué resolvió la Comisión.');
  plain('deber-buena-fe-recomendaciones','La Corte ha hablado de realizar los mejores esfuerzos para cumplir las recomendaciones; eso no convierte el informe de la Comisión en sentencia.','Al explicarlo, cita la decisión pertinente y no mezcles ese estándar con la ejecución de una sentencia.');
  plain('cidh','Es la Comisión: recibe y examina peticiones, formula recomendaciones y puede llevar ciertos casos ante la Corte. No dicta las sentencias de la Corte.','Una petición se presenta ante la CIDH; si el asunto llega a juicio, la sentencia la dicta la Corte IDH.');
  plain('corteidh','Es el tribunal del sistema interamericano. Decide casos contenciosos que le someten la Comisión o un Estado legitimado, si se cumplen las condiciones de competencia.','La Corte no recibe directamente una petición individual como si fuera una demanda inicial.');
  plain('competencia','Es la respuesta a “¿puede este órgano examinar este asunto bajo estas reglas?”. Se revisan personas, tiempo, lugar, materia e instrumento.','Que un hecho sea grave no elimina la necesidad de comprobar si el tratado y el órgano aplican a ese Estado y a ese período.');
  plain('jurisdiccion','En este contexto, es la facultad de la Corte para resolver un caso contencioso. Ser parte de la Convención no siempre basta: revisa también el reconocimiento de la competencia de la Corte.','Comprueba el depósito del tratado y la declaración o aceptación aplicable al Estado.');
  plain('agotamiento','Por regla general, antes de acudir al sistema interamericano deben usarse los recursos internos adecuados y efectivos. Hay excepciones previstas por la Convención.','No basta con listar todos los recursos del país: identifica cuál podía reparar el problema y qué ocurrió al intentarlo.');
  plain('excepciones-agotamiento','La Convención contempla excepciones si no existe debido proceso para proteger el derecho, se impidió acceder o agotar recursos, o hubo demora injustificada. Deben analizarse con hechos.','Una demora larga no prueba automáticamente retardo injustificado: explica duración, actividad y contexto del recurso.');
  plain('solucion-amistosa','Es un acuerdo voluntario que la CIDH puede facilitar. Requiere consentimiento y respeto de derechos humanos; no es una sentencia.','Si el acuerdo se aprueba, la CIDH redacta un informe que resume los hechos y la solución.');
  plain('esap','Es el escrito de las presuntas víctimas o sus representantes ante la Corte. Expone qué piden, por qué y con qué pruebas, dentro del marco del caso.','Después de recibir la notificación del caso, revisa el plazo de dos meses previsto en el Reglamento de la Corte.');
  plain('peticion-vs-caso','La petición es la comunicación inicial. Cuando la CIDH adopta una decisión de admisibilidad, el expediente puede registrarse como caso para estudiar el fondo.','Decir “mi caso” coloquialmente no significa que procesalmente ya esté en la etapa de fondo.');
  plain('informe-admisibilidad','La Comisión decide si puede continuar con el examen. Esa decisión no declara que el Estado violó derechos.','Admisible significa que se puede pasar al análisis de fondo, no que la persona ya ganó el caso.');
  plain('sentencia','Es la decisión judicial de la Corte sobre el caso sometido. Puede declarar violaciones y ordenar reparaciones, según lo que haya examinado.','Una recomendación de la Comisión no es una sentencia: para que exista sentencia debe decidir la Corte.');

  window.RI_GLOSARIO.push(
    {id:'opinion-conclusiones-articulo-51',label:'Opinión y conclusiones del artículo 51.1',aliases:['opinión de la CIDH después de tres meses','conclusiones finales artículo 51','informe artículo 51.1 CADH'],category:'Decisiones y documentos',definition:'La Convención Americana, artículo 51.1, permite que la CIDH emita su opinión y conclusiones sobre el asunto si, dentro de los tres meses desde la remisión del informe a los Estados, no se solucionó ni se sometió a la Corte por la Comisión o por un Estado interesado que haya aceptado su competencia. El Reglamento describe la etapa correlativa como emisión posible de un informe definitivo (art. 47.1). La expresión “podrá” significa que el documento no nace automáticamente por el simple vencimiento del período.',simple:'Si pasan los tres meses y el asunto sigue sin resolverse ni llegar a la Corte, la Comisión puede emitir sus conclusiones. No es automático.',example:'La fecha de transmisión ya pasó hace tres meses, pero para afirmar que existe un informe hay que localizar la decisión adoptada por la CIDH.',use:'Distingue la regla de la Convención (opinión y conclusiones) de la forma de informe desarrollada en el Reglamento. Busca si la Comisión efectivamente lo emitió.',section:'#recorrido',related:['periodo-articulo-51','informe-definitivo','informe-preliminar','sometimiento'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
    {id:'plazo-medidas-articulo-51-2',label:'Plazo para que el Estado tome medidas',aliases:['plazo artículo 51.2','plazo de cumplimiento del informe final CIDH','tiempo para remediar la situación'],category:'Plazos y escritos',definition:'Después de emitir las conclusiones previstas en el artículo 51.1, la CIDH formula recomendaciones y fija un plazo dentro del cual el Estado debe tomar las medidas que le competan para remediar la situación examinada (Convención Americana, art. 51.2). Es un plazo posterior y distinto de los tres meses anteriores y del plazo para informar que puede señalar el Reglamento en otras comunicaciones.',simple:'Primero transcurre el período de tres meses. Si la Comisión emite sus conclusiones, fija otro plazo para que el Estado tome medidas.',example:'No sumes automáticamente “tres meses más una prórroga”: identifica qué informe se emitió y qué plazo concreto fijó la Comisión.',use:'Anota el acto que fija este plazo, la fecha de inicio indicada, las medidas solicitadas y la fecha límite. No inventes una duración si la decisión no está a la vista.',section:'#reloj',related:['opinion-conclusiones-articulo-51','informe-definitivo','recomendaciones','informe-cumplimiento-estado','evaluacion-medidas-articulo-51'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
    {id:'evaluacion-medidas-articulo-51',label:'Evaluación de las medidas del Estado',aliases:['evaluación de cumplimiento artículo 51.3','decisión sobre medidas adecuadas CIDH','cumplimiento posterior a recomendaciones'],category:'Decisiones y documentos',definition:'Una vez vence el período que fijó bajo el artículo 51.2, la Comisión decide por mayoría absoluta si el Estado tomó o no medidas adecuadas. Esta valoración es un paso propio: no equivale a la mera recepción de una respuesta estatal ni se presume por el silencio del expediente (Convención Americana, art. 51.3).',simple:'Cuando termina el plazo para actuar, la Comisión valora si las medidas del Estado fueron adecuadas.',example:'El Estado informa que aprobó una medida; la Comisión debe valorar si responde realmente a la recomendación.',use:'Busca la decisión de evaluación y su fundamento. Separa lo que el Estado dice haber hecho de lo que la CIDH concluye.',section:'#seguimiento',related:['plazo-medidas-articulo-51-2','publicacion-informe-articulo-51','informe-cumplimiento-estado','mayoria-absoluta-cidh'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
    {id:'publicacion-informe-articulo-51',label:'Decisión de publicar el informe del artículo 51',aliases:['publicación artículo 51.3','publicar el informe de conclusiones CIDH','informe artículo 51 publicado'],category:'Decisiones y documentos',definition:'Después del plazo fijado para que el Estado tome medidas, la CIDH decide por mayoría absoluta dos cuestiones relacionadas pero distintas: si el Estado adoptó medidas adecuadas y si publica o no su informe (Convención Americana, art. 51.3). Bajo el Reglamento, también se prevé la evaluación de información de cumplimiento y la decisión de publicación del informe definitivo (art. 47.2–3). La publicación requiere decisión; no ocurre automáticamente al vencerse un plazo.',simple:'La Comisión decide si las medidas fueron adecuadas y si hará público el informe. Son dos decisiones relacionadas, no un efecto automático.',example:'Que el Estado haya recibido el informe no significa que ya esté publicado; comprueba la decisión de publicación.',use:'Registra por separado transmisión, respuesta estatal, evaluación de cumplimiento y decisión de publicación.',section:'#seguimiento',related:['evaluacion-medidas-articulo-51','informe-definitivo','publicacion-informe-cidh','mayoria-absoluta-cidh'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
    {id:'solucion-durante-periodo-articulo-51',label:'Solución del asunto durante el período del artículo 51',aliases:['solución durante los tres meses','acuerdo en el período artículo 51','asunto solucionado antes de la Corte'],category:'Etapas y conceptos',definition:'La Convención permite que, durante los tres meses posteriores a la remisión del informe a los Estados, el asunto se solucione. Si existe solución amistosa, la CIDH aplica las reglas del artículo 49 de la Convención y el artículo 40 de su Reglamento, que requieren consentimiento y respeto de derechos humanos. “Solucionado” no significa simplemente que una parte respondió: debe identificarse qué acuerdo o acto cerró la controversia.',simple:'Durante esos tres meses, las partes pueden alcanzar una solución; no basta con que haya intercambio de cartas.',example:'Un acuerdo puede poner fin al asunto si existe consentimiento y se aprueba el informe de solución amistosa correspondiente.',use:'Comprueba si hay un acuerdo, consentimiento de las personas afectadas cuando proceda y el informe que formaliza la solución.',section:'#recorrido',related:['periodo-articulo-51','solucion-amistosa','informe-preliminar','opinion-conclusiones-articulo-51'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
    {id:'estado-somete-caso-articulo-51',label:'Sometimiento por el Estado interesado',aliases:['Estado lleva el asunto a la Corte artículo 51','sometimiento estatal a la Corte','Estado interesado acepta competencia'],category:'Etapas y documentos',definition:'El artículo 51.1 contempla que el asunto sea sometido a la decisión de la Corte por el Estado interesado que acepte su competencia. Debe leerse junto con los artículos 61 y 62 de la Convención: solo los Estados partes y la CIDH pueden someter casos, y la Corte requiere que los Estados concernidos hayan reconocido su competencia. No equivale a la petición individual de una víctima.',simple:'La Convención menciona que el Estado interesado también puede llevar el asunto a la Corte si acepta su competencia. La víctima no presenta directamente el caso contencioso.',example:'Distingue quién presenta la petición inicial ante la CIDH y quiénes tienen capacidad convencional para someter un caso ante la Corte.',use:'Verifica instrumento, aceptación de competencia y quién realizó el acto de sometimiento; no infieras esas condiciones solo por la nacionalidad de la víctima.',section:'#corte',related:['periodo-articulo-51','sometimiento','corteidh','reconocimiento-corte','informe-articulo-50'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
    {id:'confidencialidad-informe-articulo-50',label:'Confidencialidad del informe del artículo 50',aliases:['informe preliminar no publicable','confidencialidad informe preliminar CIDH','Estado no puede publicar informe artículo 50'],category:'Decisiones y documentos',definition:'El artículo 50.2 de la Convención Americana establece que el informe se transmite a los Estados interesados, que no están facultados para publicarlo. El Reglamento, artículo 44.2, precisa que el Estado no puede publicar el informe preliminar hasta que la CIDH adopte una decisión al respecto. Esta restricción no debe confundirse con el informe que la Comisión hace público al someter el caso a la Corte (Reglamento, art. 74.3) o con la publicación decidida bajo los artículos 47 del Reglamento y 51.3 de la Convención.',simple:'El Estado recibe el informe preliminar, pero no puede hacerlo público por su cuenta mientras la Comisión no decida.',example:'La transmisión al Estado no convierte el informe en documento públicamente difundido.',use:'Comprueba qué informe tienes y si la CIDH decidió publicarlo o sometió el caso a la Corte.',section:'#recorrido',related:['informe-preliminar','informe-articulo-50','publicacion-informe-articulo-51','remision-caso-corte'],source:'https://www.oas.org/es/cidh/mandato/documentos-basicos/convencion-americana-derechos-humanos.pdf'},
    {id:'plazo-solicitud-suspension-cidh',label:'Efectos de pedir la suspensión del período',aliases:['la solicitud suspende el plazo','suspensión automática artículo 51','pedir prórroga detiene el plazo CIDH'],category:'Plazos y escritos',definition:'Presentar una solicitud de suspensión prevista en el artículo 46 del Reglamento CIDH no detiene automáticamente el período del artículo 51.1. La regla dice que la Comisión puede considerar la suspensión si se reúnen las condiciones. Por eso se debe comprobar si existe una decisión de la CIDH, qué período fijó y desde qué fecha produce efectos.',simple:'Pedir una suspensión no pausa el reloj por sí solo. Busca la decisión de la Comisión.',example:'Si solo consta la carta de solicitud del Estado, no supongas que el plazo de tres meses quedó suspendido.',use:'En la cronología registra por separado fecha de solicitud y fecha y contenido de la decisión de la CIDH.',section:'#reloj',related:['solicitud-suspension-articulo-51','suspension-articulo-51','periodo-articulo-51'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'},
    {id:'decision-expresa-cidh',label:'Decisión expresa de la CIDH',aliases:['decisión adoptada por la Comisión','la Comisión podrá emitir','acto adoptado por la CIDH'],category:'Decisiones y documentos',definition:'Acto que permite comprobar que la CIDH tomó una determinación concreta. Cuando la norma dice que la Comisión “podrá” emitir un informe o decidir sobre publicación, el transcurso de un plazo no reemplaza la adopción de esa decisión. Deben verificarse el documento, fecha, órgano y parte resolutiva.',simple:'Una posibilidad prevista en la norma no significa que la Comisión ya la haya usado. Hay que encontrar la decisión.',example:'Tres meses transcurridos no prueban, sin más, que se adoptó el informe definitivo.',use:'Busca el acto oficial antes de escribir que un informe fue emitido, publicado o que el caso fue sometido.',section:'#jurisprudencia',related:['informe-definitivo','opinion-conclusiones-articulo-51','publicacion-informe-articulo-51','resolucion-informe-sentencia'],source:'https://www.oas.org/es/cidh/jsForm/?File=%2Fes%2Fcidh%2Fmandato%2Fbasicos%2Freglamentocidh.asp'}
  );
}
